+using System.IO;
+using UnityEditor;
+using UnityEngine;
+using ChronoTraveler.Battle;
+
+namespace ChronoTraveler.EditorTools
+{
+    /// <summary>
+    /// Imports the 5 boss portraits (solid dark background — no transparency needed) as
+    /// sprites under Art/Portraits/Enemies and assigns to each boss EnemyDefinition.portrait.
+    /// Headless: -executeMethod ChronoTraveler.EditorTools.BossPortraitSetupTool.BuildPortraits
+    /// </summary>
+    public static class BossPortraitSetupTool
+    {
+        private const string SrcDir = "C:/Users/linyu/CLionProjects/final project/asset image/boss";
+        private const string OutDir = "Assets/Art/Portraits/Enemies";
+
+        // (source filename, boss id, EnemyDefinition asset path)
+        private static readonly (string src, string id, string asset)[] Map =
+        {
+            ("ChatGPT Image 2026年6月16日 02_30_59 (1).png", "china_boss",  "Assets/_Content/China/Enemies/enemy_china_boss.asset"),
+            ("ChatGPT Image 2026年6月16日 02_30_59 (2).png", "egypt_boss",  "Assets/_Content/Egypt/Enemies/egypt_boss.asset"),
+            ("ChatGPT Image 2026年6月16日 02_30_59 (3).png", "greece_boss", "Assets/_Content/Greece/Enemies/greece_boss.asset"),
+            ("ChatGPT Image 2026年6月16日 02_31_00 (4).png", "rome_boss",   "Assets/_Content/Rome/Enemies/rome_boss.asset"),
+            ("ChatGPT Image 2026年6月16日 02_31_00 (5).png", "trade_boss",  "Assets/_Content/Trade/Enemies/trade_boss.asset"),
+        };
+
+        [MenuItem("ChronoTraveler/Content/Build Boss Portraits")]
+        public static void BuildPortraits()
+        {
+            Debug.Log("[BossPortrait] === BEGIN ===");
+            if (!Directory.Exists(OutDir)) { Directory.CreateDirectory(OutDir); AssetDatabase.Refresh(); }
+
+            foreach (var (src, id, assetPath) in Map)
+            {
+                string srcPath = Path.Combine(SrcDir, src);
+                if (!File.Exists(srcPath)) { Debug.LogError($"[BossPortrait] missing {src}"); continue; }
+
+                string outPath = $"{OutDir}/{id}.png";
+                File.Copy(srcPath, outPath, true);
+                AssetDatabase.ImportAsset(outPath, ImportAssetOptions.ForceUpdate);
+
+                var ti = AssetImporter.GetAtPath(outPath) as TextureImporter;
+                if (ti != null)
+                {
+                    ti.textureType = TextureImporterType.Sprite;
+                    ti.spriteImportMode = SpriteImportMode.Single;
+                    ti.SaveAndReimport();
+                }
+
+                var sprite = AssetDatabase.LoadAssetAtPath<Sprite>(outPath);
+                var enemy = AssetDatabase.LoadAssetAtPath<EnemyDefinition>(assetPath);
+                if (enemy != null && sprite != null)
+                {
+                    enemy.portrait = sprite;
+                    EditorUtility.SetDirty(enemy);
+                    Debug.Log($"[BossPortrait] {id}: portrait assigned.");
+                }
+                else Debug.LogWarning($"[BossPortrait] {id}: enemy={enemy != null} sprite={sprite != null}");
+            }
+
+            AssetDatabase.SaveAssets();
+            AssetDatabase.Refresh();
+            Debug.Log("[BossPortrait] === DONE ===");
+        }
+    }
+}

diff --git a/ChronoTraveler/Assets/Editor/NPCPortraitSetupTool.cs b/ChronoTraveler/Assets/Editor/NPCPortraitSetupTool.cs
new file mode 100644
index 0000000..e31e01f
--- /dev/null
+++ b/ChronoTraveler/Assets/Editor/NPCPortraitSetupTool.cs
@@ -0,0 +1,113 @@
+using System.Collections.Generic;
+using System.IO;
+using UnityEditor;
+using UnityEngine;
+
+namespace ChronoTraveler.EditorTools
+{
+    /// <summary>
+    /// Imports the 15 era-NPC dialogue 立绘: strips the painted "fake transparency"
+    /// checkerboard (flood-fill from corners keying bright low-saturation grays → alpha 0),
+    /// saves each as a transparent sprite under Resources/Portraits/&lt;npcId&gt; so DialogueUI
+    /// can load it via Resources.Load&lt;Sprite&gt;("Portraits/" + npcId). Source files in the
+    /// shared art folder are already named by npcId.
+    /// Headless: -executeMethod ChronoTraveler.EditorTools.NPCPortraitSetupTool.BuildPortraits
+    /// </summary>
+    public static class NPCPortraitSetupTool
+    {
+        private const string SrcDir = "C:/Users/linyu/CLionProjects/final project/asset image/NPC";
+        private const string OutDir = "Assets/Resources/Portraits";
+
+        private static readonly string[] NpcIds =
+        {
+            "npc_china_historian", "npc_china_artisan", "npc_china_guardian",
+            "npc_egypt_scribe", "npc_egypt_priest", "npc_egypt_guardian",
+            "npc_greece_sage", "npc_greece_historian", "npc_greece_guardian",
+            "npc_rome_senator", "npc_rome_engineer", "npc_rome_guardian",
+            "npc_trade_leader", "npc_trade_monk", "npc_trade_guardian",
+        };
+
+        [MenuItem("ChronoTraveler/Content/Build NPC Portraits")]
+        public static void BuildPortraits()
+        {
+            Debug.Log("[NPCPortrait] === BEGIN ===");
+            if (!Directory.Exists(OutDir)) { Directory.CreateDirectory(OutDir); AssetDatabase.Refresh(); }
+
+            int ok = 0;
+            foreach (var id in NpcIds)
+            {
+                string srcPath = Path.Combine(SrcDir, id + ".png");
+                if (!File.Exists(srcPath)) { Debug.LogError($"[NPCPortrait] missing source {id}.png"); continue; }
+
+                var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false);
+                tex.LoadImage(File.ReadAllBytes(srcPath));
+                RemoveCheckerBackground(tex);
+
+                string outPath = $"{OutDir}/{id}.png";
+                File.WriteAllBytes(outPath, tex.EncodeToPNG());
+                Object.DestroyImmediate(tex);
+                AssetDatabase.ImportAsset(outPath, ImportAssetOptions.ForceUpdate);
+
+                var ti = AssetImporter.GetAtPath(outPath) as TextureImporter;
+                if (ti != null)
+                {
+                    ti.textureType = TextureImporterType.Sprite;
+                    ti.spriteImportMode = SpriteImportMode.Single;
+                    ti.alphaIsTransparency = true;
+                    ti.mipmapEnabled = false;
+                    ti.SaveAndReimport();
+                }
+
+                var sprite = AssetDatabase.LoadAssetAtPath<Sprite>(outPath);
+                if (sprite != null) { ok++; Debug.Log($"[NPCPortrait] {id}: imported."); }
+                else Debug.LogWarning($"[NPCPortrait] {id}: sprite load failed.");
+            }
+
+            AssetDatabase.SaveAssets();
+            AssetDatabase.Refresh();
+            Debug.Log($"[NPCPortrait] === DONE ({ok}/{NpcIds.Length}) ===");
+        }
+
+        /// <summary>Flood-fill from the 4 corners, clearing connected bright low-saturation
+        /// (checkerboard) pixels to transparent. The centered character silhouette blocks
+        /// the fill, so interior light clothing is preserved.</summary>
+        private static void RemoveCheckerBackground(Texture2D tex)
+        {
+            int w = tex.width, h = tex.height;
+            var px = tex.GetPixels32();
+            var visited = new bool[w * h];
+            var stack = new Stack<int>();
+
+            void TryPush(int x, int y)
+            {
+                if (x < 0 || y < 0 || x >= w || y >= h) return;
+                int i = y * w + x;
+                if (visited[i]) return;
+                visited[i] = true;
+                if (IsCheckerBg(px[i])) stack.Push(i);
+            }
+
+            TryPush(0, 0); TryPush(w - 1, 0); TryPush(0, h - 1); TryPush(w - 1, h - 1);
+
+            while (stack.Count > 0)
+            {
+                int i = stack.Pop();
+                px[i] = new Color32(px[i].r, px[i].g, px[i].b, 0);
+                int x = i % w, y = i / w;
+                TryPush(x + 1, y); TryPush(x - 1, y); TryPush(x, y + 1); TryPush(x, y - 1);
+            }
+
+            tex.SetPixels32(px);
+            tex.Apply();
+        }
+
+        // Checkerboard = bright (light gray/white) and low saturation (gray).
+        private static bool IsCheckerBg(Color32 c)
+        {
+            int max = Mathf.Max(c.r, Mathf.Max(c.g, c.b));
+            int min = Mathf.Min(c.r, Mathf.Min(c.g, c.b));
+            int brightness = (c.r + c.g + c.b) / 3;
+            return (max - min) <= 26 && brightness >= 168;
+        }
+    }
+}

