@@ -0,0 +1,247 @@
+using UnityEditor;
+using UnityEngine;
+
+namespace ChronoTraveler.EditorTools
+{
+    /// <summary>
+    /// Configures the converted Astraea FBX as a Unity Humanoid and reports whether the
+    /// auto bone-mapping produced a valid human avatar (MMD's Japanese bone names are the
+    /// risk). Local trial — the FBX lives under the gitignored _ModelTest folder.
+    /// Headless: -executeMethod ChronoTraveler.EditorTools.ModelHumanoidSetup.SetupHumanoid
+    /// </summary>
+    public static class ModelHumanoidSetup
+    {
+        private const string Fbx = "Assets/_ModelTest/Astraea/Astraea.fbx";
+
+        [MenuItem("ChronoTraveler/Content/Dump Astraea Bones")]
+        public static void DumpBones()
+        {
+            var root = AssetDatabase.LoadAssetAtPath<GameObject>(Fbx);
+            if (root == null) { Debug.LogError("[Bones] FBX not found"); return; }
+            var inst = Object.Instantiate(root);
+            var all = inst.GetComponentsInChildren<Transform>(true);
+            Debug.Log($"[Bones] total transforms = {all.Length}");
+            // Print the standard MMD deform bones we care about so we can map them.
+            string[] keys = { "センター", "グルーブ", "下半身", "上半身", "首", "頭", "肩", "腕", "ひじ",
+                              "手首", "足", "ひざ", "足首", "つま先", "足先", "親指", "人指", "中指", "薬指", "小指", "目" };
+            foreach (var t in all)
+                foreach (var k in keys)
+                    if (t.name.Contains(k)) { Debug.Log($"[Bones] {t.name}"); break; }
+            Object.DestroyImmediate(inst);
+        }
+
+        [MenuItem("ChronoTraveler/Content/Dump Astraea Hierarchy")]
+        public static void DumpHierarchy()
+        {
+            var root = AssetDatabase.LoadAssetAtPath<GameObject>(Fbx);
+            var inst = Object.Instantiate(root);
+            string[] targets = { "足.L", "上半身", "頭", "肩.L", "腕.L" };
+            foreach (var name in targets)
+            {
+                Transform t = FindByName(inst.transform, name);
+                if (t == null) { Debug.Log($"[Hier] {name}: NOT FOUND"); continue; }
+                var chain = "";
+                for (var c = t; c != null && c != inst.transform; c = c.parent) chain += c.name + " ← ";
+                Debug.Log($"[Hier] {chain}(root)");
+            }
+            Object.DestroyImmediate(inst);
+        }
+
+        private static Transform FindByName(Transform root, string name)
+        {
+            foreach (var t in root.GetComponentsInChildren<Transform>(true))
+                if (t.name == name) return t;
+            return null;
+        }
+
+        // Unity humanName ← exact MMD deform-bone name (this model uses .L/.R suffixes).
+        private static readonly (string human, string bone)[] Map =
+        {
+            ("Hips", "センター"), ("Spine", "上半身"), ("Chest", "上半身2"),
+            ("Neck", "首"), ("Head", "頭"),
+            ("LeftShoulder", "肩.L"), ("LeftUpperArm", "腕.L"), ("LeftLowerArm", "ひじ.L"), ("LeftHand", "手首.L"),
+            ("RightShoulder", "肩.R"), ("RightUpperArm", "腕.R"), ("RightLowerArm", "ひじ.R"), ("RightHand", "手首.R"),
+            // legs: the mesh is skinned to the "D" leg bones (足D/ひざD/足首D), not the FK set
+            ("LeftUpperLeg", "足D.L"), ("LeftLowerLeg", "ひざD.L"), ("LeftFoot", "足首D.L"), ("LeftToes", "足先EX.L"),
+            ("RightUpperLeg", "足D.R"), ("RightLowerLeg", "ひざD.R"), ("RightFoot", "足首D.R"), ("RightToes", "足先EX.R"),
+        };
+
+        /// <summary>The FBX materials import white under URP; reuse the textured URP materials
+        /// the PMX import already built (mat_0..mat_N, same model/material order).</summary>
+        public static void FixRiggedMaterials()
+        {
+            string dir = System.IO.Path.GetDirectoryName(Fbx);
+            var prefab = AssetDatabase.LoadAssetAtPath<GameObject>($"{dir}/AstraeaRigged.prefab");
+            var inst = (GameObject)PrefabUtility.InstantiatePrefab(prefab);
+            var smr = inst.GetComponentInChildren<SkinnedMeshRenderer>();
+            int n = smr.sharedMaterials.Length;
+            var mats = new Material[n];
+            int found = 0;
+            for (int i = 0; i < n; i++)
+            {
+                mats[i] = AssetDatabase.LoadAssetAtPath<Material>($"{dir}/mat_{i}.mat");
+                if (mats[i] != null) found++;
+            }
+            smr.sharedMaterials = mats;
+            PrefabUtility.ApplyPrefabInstance(inst, InteractionMode.AutomatedAction);
+            Object.DestroyImmediate(inst);
+            Debug.Log($"[Mat] assigned {found}/{n} PMX materials to rigged prefab");
+        }
+
+        /// <summary>Drive the rigged model into a clear humanoid pose (T-pose + a bent pose)
+        /// to confirm the muscles deform the mesh correctly. Needs graphics (omit -nographics).</summary>
+        public static void CaptureRiggedPose()
+        {
+            string dir = System.IO.Path.GetDirectoryName(Fbx);
+            var prefab = AssetDatabase.LoadAssetAtPath<GameObject>($"{dir}/AstraeaRigged.prefab");
+            if (prefab == null) { Debug.LogError("[Pose] rigged prefab missing"); return; }
+            var avatar = AssetDatabase.LoadAssetAtPath<Avatar>($"{dir}/AstraeaAvatar.asset");
+
+            UnityEditor.SceneManagement.EditorSceneManager.NewScene(
+                UnityEditor.SceneManagement.NewSceneSetup.EmptyScene,
+                UnityEditor.SceneManagement.NewSceneMode.Single);
+            var l = new GameObject("Sun").AddComponent<Light>();
+            l.type = LightType.Directional; l.intensity = 1.2f;
+            l.transform.rotation = Quaternion.Euler(40, 160, 0);
+            RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Flat;
+            RenderSettings.ambientLight = new Color(0.55f, 0.55f, 0.6f);
+
+            var go = (GameObject)PrefabUtility.InstantiatePrefab(prefab);
+            go.transform.position = Vector3.zero;
+
+            var handler = new HumanPoseHandler(avatar, go.transform);
+            var pose = new HumanPose();
+            handler.GetHumanPose(ref pose);

