@@ -0,0 +1,122 @@
+using System.IO;
+using UnityEditor;
+using UnityEditor.Animations;
+using UnityEngine;
+
+namespace ChronoTraveler.EditorTools
+{
+    /// <summary>
+    /// Imports the downloaded Mixamo animation FBXs as Humanoid (so they retarget to the
+    /// Astraea avatar), loops the locomotion clips, and reports each clip's length / loop /
+    /// root-motion so we can verify they fit. Local trial — under gitignored _ModelTest.
+    /// Headless: -executeMethod ChronoTraveler.EditorTools.AnimationImportSetup.ImportAndInspect
+    /// </summary>
+    public static class AnimationImportSetup
+    {
+        private const string SrcDir = "C:/Users/linyu/CLionProjects/final project/asset model/skeletal animation";
+        private const string OutDir = "Assets/_ModelTest/Animations";
+
+        [MenuItem("ChronoTraveler/Content/Import Astraea Animations")]
+        public static void ImportAndInspect()
+        {
+            Debug.Log("[Anim] === BEGIN ===");
+            Directory.CreateDirectory(OutDir);
+            AssetDatabase.Refresh();
+
+            foreach (var src in Directory.GetFiles(SrcDir, "*.fbx"))
+            {
+                string name = Path.GetFileName(src);
+                string dst = $"{OutDir}/{name}";
+                File.Copy(src, dst, true);
+                AssetDatabase.ImportAsset(dst, ImportAssetOptions.ForceUpdate);
+
+                var imp = AssetImporter.GetAtPath(dst) as ModelImporter;
+                if (imp == null) { Debug.LogError($"[Anim] no importer for {name}"); continue; }
+                imp.animationType = ModelImporterAnimationType.Human;
+                imp.avatarSetup = ModelImporterAvatarSetup.CreateFromThisModel;
+
+                bool loco = !name.ToLower().Contains("button");
+                var clips = imp.defaultClipAnimations;
+                for (int i = 0; i < clips.Length; i++) clips[i].loopTime = loco;
+                imp.clipAnimations = clips;
+                imp.SaveAndReimport();
+
+                // inspect
+                var root = AssetDatabase.LoadAssetAtPath<GameObject>(dst);
+                var anim = root != null ? root.GetComponent<Animator>() : null;
+                bool human = anim != null && anim.avatar != null && anim.avatar.isHuman;
+                foreach (var a in AssetDatabase.LoadAllAssetsAtPath(dst))
+                {
+                    if (a is AnimationClip c && !c.name.StartsWith("__preview"))
+                        Debug.Log($"[Anim] {name}: clip='{c.name}' len={c.length:F2}s loop={c.isLooping} " +
+                                  $"rootSpeed={c.averageSpeed.magnitude:F2} human={human}");
+                }
+            }
+            AssetDatabase.SaveAssets(); AssetDatabase.Refresh();
+            Debug.Log("[Anim] === DONE ===");
+        }
+
