+
+            var bytes = File.ReadAllBytes(srcPmx);
+            using var r = new BinaryReader(new MemoryStream(bytes));
+
+            // header
+            r.ReadBytes(4); r.ReadSingle();
+            byte gc = r.ReadByte(); byte[] g = r.ReadBytes(gc);
+            int enc = g[0], addUV = g[1], vIdx = g[2], texIdx = g[3], matIdx = g[4], boneIdx = g[5];
+            ReadText(r, enc); ReadText(r, enc); ReadText(r, enc); ReadText(r, enc);
