+                    case 1: r.ReadBytes(boneIdx * 2); r.ReadSingle(); break;
+                    case 2: r.ReadBytes(boneIdx * 4); r.ReadBytes(16); break;
+                    case 3: r.ReadBytes(boneIdx * 2); r.ReadBytes(4 + 36); break;
+                    case 4: r.ReadBytes(boneIdx * 4); r.ReadBytes(16); break;
