+        private const float TargetHeight = 15f; // metres for the tallest element (the temple)
+
+        [MenuItem("ChronoTraveler/Content/Build Temple Stage")]
+        public static void BuildTemple()
+        {
+            var imp = AssetImporter.GetAtPath(Fbx) as ModelImporter;
+            if (imp == null) { Debug.LogError("[Temple] FBX missing"); return; }
+            imp.animationType = ModelImporterAnimationType.None;
+            imp.importCameras = false; imp.importLights = false;
+            imp.materialImportMode = ModelImporterMaterialImportMode.ImportStandard; // keep per-object slots/names
+            imp.SaveAndReimport();
+
+            // copy textures into the project
+            Directory.CreateDirectory(TexDir); Directory.CreateDirectory(MatDir);
+            foreach (var f in Directory.GetFiles(TexSrc))
+            {
+                string ext = Path.GetExtension(f).ToLower();
+                if (ext != ".jpg" && ext != ".jpeg" && ext != ".png") continue;
+                File.Copy(f, $"{TexDir}/{Path.GetFileName(f)}", true);
+            }
+            AssetDatabase.Refresh();
+            // normal maps → Normal type
+            foreach (var t in Directory.GetFiles(TexDir, "*.*"))
+            {
+                if (t.EndsWith(".meta")) continue;
+                if (t.ToLower().Contains("normal"))
+                {
+                    var ti = AssetImporter.GetAtPath(t.Replace('\\', '/')) as TextureImporter;
+                    if (ti != null && ti.textureType != TextureImporterType.NormalMap)
+                    { ti.textureType = TextureImporterType.NormalMap; ti.SaveAndReimport(); }
+                }
+            }
+
+            var texFiles = new List<string>(Directory.GetFiles(TexDir));
+            texFiles.RemoveAll(p => p.EndsWith(".meta"));
+
+            var fbx = AssetDatabase.LoadAssetAtPath<GameObject>(Fbx);
+            var inst = (GameObject)PrefabUtility.InstantiatePrefab(fbx);
+            var cache = new Dictionary<string, Material>();
+            int matched = 0, total = 0;
+            foreach (var r in inst.GetComponentsInChildren<Renderer>())
+            {
+                var slots = r.sharedMaterials;
+                for (int i = 0; i < slots.Length; i++)
+                {
+                    if (slots[i] == null) continue;
+                    string key = slots[i].name;
+                    if (!cache.TryGetValue(key, out var m)) { m = BuildMat(key, texFiles, ref matched); cache[key] = m; total++; }
+                    slots[i] = m;
+                }
+                r.sharedMaterials = slots;
+            }
+            Debug.Log($"[Temple] materials built={total} (baseColor matched={matched})");
+
+            // scale to sane size
+            var b = new Bounds(inst.transform.position, Vector3.zero);
+            foreach (var r in inst.GetComponentsInChildren<Renderer>()) b.Encapsulate(r.bounds);
+            float scale = b.size.y > 0.01f ? TargetHeight / b.size.y : 1f;
+            inst.transform.localScale = Vector3.one * scale;
+            Debug.Log($"[Temple] raw size {b.size.x:F0}×{b.size.y:F0}×{b.size.z:F0}m → scale {scale:F3} → {b.size.x * scale:F1}×{b.size.y * scale:F1}×{b.size.z * scale:F1}m");
+
+            PrefabUtility.SaveAsPrefabAsset(inst, $"{Dir}/TempleStage.prefab");
+            Object.DestroyImmediate(inst);
+            AssetDatabase.SaveAssets(); AssetDatabase.Refresh();
+            Debug.Log($"[Temple] === DONE → {Dir}/TempleStage.prefab ===");
+        }
+
+        private static Material BuildMat(string name, List<string> texFiles, ref int matched)
+        {
+            var m = new Material(Shader.Find("Universal Render Pipeline/Lit")) { name = name };
+            string clean = Regex.Replace(name, @"\.\d+$", "").ToLower(); // strip Blender .001 suffix
+            string baseTex = Find(texFiles, clean, "basecolor", "diffuse");
+            string normTex = Find(texFiles, clean, "normal");
+            if (baseTex != null)
+            {
+                var t = AssetDatabase.LoadAssetAtPath<Texture2D>(baseTex);
+                m.SetTexture("_BaseMap", t); m.mainTexture = t; matched++;
+            }
+            else m.SetColor("_BaseColor", new Color(0.7f, 0.68f, 0.64f)); // neutral fallback
+            if (normTex != null)
+            {
+                var nt = AssetDatabase.LoadAssetAtPath<Texture2D>(normTex);
+                if (nt != null) { m.SetTexture("_BumpMap", nt); m.EnableKeyword("_NORMALMAP"); }
+            }
+            m.SetFloat("_Smoothness", 0.2f);
+            AssetDatabase.CreateAsset(m, $"{MatDir}/{Sanitize(name)}.mat");
+            return m;
+        }
+
+        private static string Find(List<string> files, string clean, params string[] kinds)
+        {

