+using System.Text.RegularExpressions;
+using UnityEditor;
+using UnityEngine;
+using UnityEngine.Rendering;
+
+namespace ChronoTraveler.EditorTools
+{
+    /// <summary>
+    /// Imports the FULL temple-valley environment (TempleFull.fbx) as the playable China
+    /// level: scale to human size, mesh colliders for walking, PBR→URP materials by texture
+    /// name (+ green foliage / stone fallbacks), prefab. Plus framed captures to verify it
+    /// matches the concept (gate → winding path → temple).
+    /// Headless: -executeMethod ChronoTraveler.EditorTools.FullEnvSetup.BuildFullEnv
+    /// </summary>
+    public static class FullEnvSetup
+    {
+        private const string Dir = "Assets/Art/Environments/Temple";
+        private const string Fbx = Dir + "/TempleFull.fbx";
+        private const string TexSrc = "C:/Users/linyu/CLionProjects/final project/asset model/古寺_by_yuyaoxiong_40edce665ee9e5ec09614951f32ebcc2/古寺/textures";
+        private const string TexDir = Dir + "/TexFull";
+        private const string MatDir = Dir + "/MatFull";
+        private const float Scale = 0.25f; // MMD-ish units → ~human scale
+
+        [MenuItem("ChronoTraveler/Content/Build Full Temple Env")]
+        public static void BuildFullEnv()
+        {
+            var imp = AssetImporter.GetAtPath(Fbx) as ModelImporter;
+            if (imp == null) { Debug.LogError("[Full] FBX missing at " + Fbx); return; }
+            imp.animationType = ModelImporterAnimationType.None;
+            imp.importCameras = false; imp.importLights = false;
+            imp.addCollider = true; // mesh colliders for walking
+            imp.materialImportMode = ModelImporterMaterialImportMode.ImportStandard;
+            imp.SaveAndReimport();
+
+            // textures
+            Directory.CreateDirectory(TexDir); Directory.CreateDirectory(MatDir);
+            foreach (var f in Directory.GetFiles(TexSrc))
+            {
+                string e = Path.GetExtension(f).ToLower();
+                if (e == ".jpg" || e == ".jpeg" || e == ".png") File.Copy(f, $"{TexDir}/{Path.GetFileName(f)}", true);
+            }
+            AssetDatabase.Refresh();
+            foreach (var t in Directory.GetFiles(TexDir))
+                if (!t.EndsWith(".meta") && t.ToLower().Contains("normal"))
+                {
+                    var ti = AssetImporter.GetAtPath(t.Replace('\\', '/')) as TextureImporter;
+                    if (ti != null && ti.textureType != TextureImporterType.NormalMap) { ti.textureType = TextureImporterType.NormalMap; ti.SaveAndReimport(); }
+                }
+            var texFiles = new List<string>(Directory.GetFiles(TexDir)); texFiles.RemoveAll(p => p.EndsWith(".meta"));
+
+            var fbx = AssetDatabase.LoadAssetAtPath<GameObject>(Fbx);
+            var inst = (GameObject)PrefabUtility.InstantiatePrefab(fbx);
+            inst.transform.localScale = Vector3.one * Scale;
+
+            var cache = new Dictionary<string, Material>();
+            int matched = 0;
+            foreach (var r in inst.GetComponentsInChildren<Renderer>())
+            {
+                var slots = r.sharedMaterials;
+                for (int i = 0; i < slots.Length; i++)
+                {
+                    if (slots[i] == null) continue;
+                    string key = slots[i].name;
+                    if (!cache.TryGetValue(key, out var m)) { m = BuildMat(key, texFiles, ref matched); cache[key] = m; }
+                    slots[i] = m;
+                }
+                r.sharedMaterials = slots;
+            }
+
+            var b = new Bounds(inst.transform.position, Vector3.zero);
+            foreach (var r in inst.GetComponentsInChildren<Renderer>()) b.Encapsulate(r.bounds);
+            Debug.Log($"[Full] materials={cache.Count} matched={matched} worldSize≈{b.size.x:F0}×{b.size.y:F0}×{b.size.z:F0}m center={b.center}");
+
+            PrefabUtility.SaveAsPrefabAsset(inst, $"{Dir}/TempleFull.prefab");
+            Object.DestroyImmediate(inst);
+            AssetDatabase.SaveAssets(); AssetDatabase.Refresh();
+            Debug.Log($"[Full] === DONE → {Dir}/TempleFull.prefab ===");
+        }
+
+        private static Material BuildMat(string name, List<string> texFiles, ref int matched)
+        {
+            var m = new Material(Shader.Find("Universal Render Pipeline/Lit")) { name = name };
+            string clean = Regex.Replace(name, @"\.\d+$", "").ToLower();
+            string baseTex = Find(texFiles, clean, "basecolor", "diffuse");
+            string normTex = Find(texFiles, clean, "normal");
+            if (baseTex != null) { var t = AssetDatabase.LoadAssetAtPath<Texture2D>(baseTex); m.SetTexture("_BaseMap", t); m.mainTexture = t; matched++; }
+            else
+            {
+                // heuristic fallback: foliage→green, ground→mossy, else stone-gray
+                string n = clean;
+                Color c = new Color(0.5f, 0.48f, 0.45f);
+                if (n.Contains("leaf") || n.Contains("tree") || n.Contains("obj3d") || n.Contains("foli") || n.Contains("grass") || n.Contains("plant")) c = new Color(0.28f, 0.42f, 0.22f);
+                else if (n.Contains("ground") || n.Contains("land") || n.Contains("terrain") || n.Contains("moss")) c = new Color(0.33f, 0.40f, 0.26f);
+                m.SetColor("_BaseColor", c);
+            }
+            if (normTex != null) { var nt = AssetDatabase.LoadAssetAtPath<Texture2D>(normTex); if (nt != null) { m.SetTexture("_BumpMap", nt); m.EnableKeyword("_NORMALMAP"); } }
+            m.SetFloat("_Smoothness", 0.1f);
+            AssetDatabase.CreateAsset(m, $"{MatDir}/{Regex.Replace(name, @"[^\w\-]", "_")}.mat");
+            return m;
+        }
+
+        private static string Find(List<string> files, string clean, params string[] kinds)
+        {
+            var toks = Regex.Split(clean, @"[^a-z0-9]+");
+            string best = null; int bestScore = 0;
+            foreach (var f in files)
+            {
+                string n = Path.GetFileNameWithoutExtension(f).ToLower();
+                bool ok = false; foreach (var k in kinds) if (n.Contains(k)) { ok = true; break; }
+                if (!ok) continue;
+                int p = 0; while (p < n.Length && p < clean.Length && n[p] == clean[p]) p++;
+                int tok = 0; foreach (var ct in toks) if (ct.Length >= 4 && n.Contains(ct)) tok = Mathf.Max(tok, ct.Length);

