+            float baseY = bb.min.y, cx = bb.center.x, frontZ = bb.min.z;
+            float rampTopZ = frontZ - 18f, rampBotZ = rampTopZ - 22f, drop = 9f, rampW = 12f, span = rampTopZ - rampBotZ;
+
+            foreach (var o in GameObject.FindObjectsByType<GameObject>(FindObjectsSortMode.None))
