diff --git a/ChronoTraveler/Assets/Scripts/World/AnomalyVisual.cs b/ChronoTraveler/Assets/Scripts/World/AnomalyVisual.cs
new file mode 100644
index 0000000..a24a3f6
--- /dev/null
+++ b/ChronoTraveler/Assets/Scripts/World/AnomalyVisual.cs
@@ -0,0 +1,173 @@
+using System.Collections.Generic;
+using UnityEngine;
+using ChronoTraveler.Battle;
+
+namespace ChronoTraveler.World
+{
+    /// <summary>
+    /// Turns a plain emissive sphere (the gray-box 错乱体) into an eldritch, Cthulhu-flavoured
+    /// anomaly, driven by the "ChronoTraveler/Anomaly" GPU shader (writhing fbm displacement +
+    /// spiky tendrils, flowing veins, fresnel rim, iridescence, pulse) tinted from the sphere's
+    /// existing glow. A slowly orbiting ring of jagged shards adds menace.
+    ///
+    /// Bosses are differentiated beyond size (<see cref="Configure"/>): heavier/slower ominous
+    /// pulse and bigger tendrils, a second counter-rotating shard ring, an outward "spike crown",
+    /// and — when the boss has phase elements — the whole mass slowly roils through those element
+    /// colours, telegraphing the multi-element fight.
+    ///
+    /// Self-contained: BattleTrigger adds + configures it at runtime, so every anomaly upgrades
+    /// with no asset/scene/tool changes. Degrades gracefully if the shader is missing.
+    /// </summary>
+    [RequireComponent(typeof(MeshFilter), typeof(MeshRenderer))]
+    public class AnomalyVisual : MonoBehaviour
+    {
+        private bool isBoss;
+        private ElementType[] phases;
+
+        private Material mainMat;
+        private readonly List<(Transform ring, Vector3 axis, float speed)> rings = new List<(Transform, Vector3, float)>();
+
+        /// <summary>Called by BattleTrigger right after AddComponent (before Start).</summary>
+        public void Configure(bool boss, ElementType[] phaseElements)
+        {
+            isBoss = boss;
+            phases = phaseElements;
+        }
+
+        private void Start()
+        {
+            var mr = GetComponent<MeshRenderer>();
+            var mf = GetComponent<MeshFilter>();
+            if (mr == null || mf == null || mf.sharedMesh == null) { enabled = false; return; }
+
+            Color glow = ReadGlow(mr.sharedMaterial);
+
+            var shader = Shader.Find("ChronoTraveler/Anomaly");
+            if (shader == null)
+            {
+                Debug.LogWarning("[AnomalyVisual] 'ChronoTraveler/Anomaly' shader not found; keeping base material.");
+                enabled = false;
+                return;
+            }
+
+            // Instance + grow bounds so GPU displacement isn't frustum-culled.
+            var mesh = Instantiate(mf.sharedMesh);
+            var b = mesh.bounds; b.Expand(b.size * (isBoss ? 2.2f : 1.6f)); mesh.bounds = b;
+            mf.mesh = mesh;
+
+            mainMat = BuildAnomalyMat(shader, glow, isBoss);
+            mr.material = mainMat;
+
+            if (isBoss)
+            {
+                BuildRing(mainMat, 8, 0.86f, () => Vector3.one * Random.Range(0.13f, 0.22f), true,
+                          new Vector3(0.3f, 1f, 0.15f), 28f);                       // debris ring
+                BuildRing(mainMat, 6, 0.62f, () => new Vector3(0.07f, 0.07f, 0.85f), false,
+                          new Vector3(0.1f, 1f, 0.4f), -18f);                        // outward spike crown
+            }
+            else
+            {
+                BuildRing(mainMat, 5, 0.72f, () => Vector3.one * Random.Range(0.12f, 0.2f), true,
+                          new Vector3(0.35f, 1f, 0.2f), 35f);
+            }
+        }
+
+        private void Update()
+        {
+            foreach (var r in rings)
+                if (r.ring != null) r.ring.Rotate(r.axis, r.speed * Time.deltaTime, Space.Self);
+
+            // Boss only: slowly roil the whole mass through its phase-element colours.
+            if (isBoss && mainMat != null && phases != null && phases.Length > 0)
+            {
+                float f = Time.time * 0.22f;
+                int n = phases.Length;
+                int a = ((int)f) % n;
+                int bx = (a + 1) % n;
+                float frac = f - Mathf.Floor(f);
+                Color c = Color.Lerp(ElementColor(phases[a]), ElementColor(phases[bx]), frac);
+                mainMat.SetColor("_BaseColor", c);
+                mainMat.SetColor("_VeinColor", c * 0.08f);
+                mainMat.SetColor("_RimColor", Color.Lerp(c, Color.white, 0.55f));
+            }
+        }
+
+        // ---- builders ----
+
+        private void BuildRing(Material mat, int count, float radius, System.Func<Vector3> scaleFn,
+                               bool randomRot, Vector3 axis, float speed)
+        {
+            if (count <= 0) return;
+            var ring = new GameObject(randomRot ? "ShardRing" : "SpikeCrown").transform;
+            ring.SetParent(transform, false);
+
+            for (int i = 0; i < count; i++)
+            {
+                var s = GameObject.CreatePrimitive(PrimitiveType.Cube);
+                s.name = $"Frag_{i}";
+                Destroy(s.GetComponent<Collider>());
+                s.transform.SetParent(ring, false);
+
+                float ang = (360f / count) * i * Mathf.Deg2Rad;
+                Vector3 outward = new Vector3(Mathf.Cos(ang), Mathf.Sin(ang * 1.6f) * 0.25f, Mathf.Sin(ang));
+                s.transform.localPosition = outward.normalized * radius;
+                s.transform.localScale = scaleFn();

