@@ -0,0 +1,279 @@
+using System.Collections.Generic;
+using UnityEditor;
+using UnityEngine;
+using ChronoTraveler.World;
+
+namespace ChronoTraveler.Editor
+{
+    /// <summary>
+    /// One-click tuning for the Hub's 5 era portals: arranges them in a regular pentagon
+    /// (one vertex up) on the magic-circle's inner ring, facing centre, and gives each era a
+    /// distinct colour (emissive disc material + matching glow light) so they read clearly in-game
+    /// instead of all-white.
+    ///
+    /// RADIUS: drag ONE portal onto the ring you want (the innermost), keep it selected, then run the
+    /// menu — the tool uses that portal's distance-from-centre as the pentagon radius. (Aborts with a
+    /// prompt if no portal is selected, so the radius is always something you chose on-screen.)
+    /// </summary>
+    public static class HubPortalFixTool
+    {
+        // Emission is normalised so every era glows at the SAME modest brightness regardless of hue.
+        // (A flat multiplier let bright hues — turquoise/amber — exceed the Hub bloom threshold and
+        // wash out to white, while dark red stayed coloured. Peak below ~0.8 avoids that blow-out.)
+        private const float EmissionPeak = 0.7f;
+
+        // Era → colour. Distinct, well-separated hues themed to each civilisation.
+        private static readonly (string scene, string label, Color color)[] Eras =
+        {
+            ("20_China",       "华夏·朱红",  new Color(0.90f, 0.20f, 0.16f)), // vermilion red
+            ("30_Egypt",       "尼罗·松石",  new Color(0.10f, 0.78f, 0.72f)), // turquoise
+            ("40_Greece",      "爱琴·湛蓝",  new Color(0.25f, 0.50f, 0.98f)), // azure
+            ("50_Rome",        "永恒·帝紫",  new Color(0.66f, 0.26f, 0.88f)), // imperial purple
+            ("60_TradeRoutes", "丝路·驼金",  new Color(0.98f, 0.70f, 0.12f)), // amber gold
+        };
+
+        [MenuItem("ChronoTraveler/Content/Fix Hub Portals (pentagon + colors)")]
+        public static void FixHubPortals()
+        {
+            var portals = Object.FindObjectsByType<Portal>(FindObjectsSortMode.None);
+            if (portals.Length == 0)
+            {
+                EditorUtility.DisplayDialog("Fix Hub Portals",
+                    "未找到任何 Portal。请先打开 10_Hub 场景再运行。\nNo Portal found — open 10_Hub first.", "OK");
+                return;
+            }
+
+            // Centre = the magic circle's centre. Prefer the HubPalace position; else world origin.
+            var palace = GameObject.Find("HubPalace");
+            Vector3 center = palace != null ? palace.transform.position : Vector3.zero;
+            center.y = 0f;
+
+            // Radius + height come from a portal you've dragged onto the target ring and selected.
+            var sel = Selection.activeGameObject;
+            var selPortal = sel != null ? sel.GetComponentInParent<Portal>() : null;
+            if (selPortal == null)
+            {
+                EditorUtility.DisplayDialog("Fix Hub Portals",
+                    "请先在场景里把【任意一个传送门】拖到你想要的圆环（最内圈）上，并保持选中它，再运行本菜单。\n" +
+                    "First drag ONE portal onto the target (innermost) ring and keep it selected, then run this menu.",
+                    "OK");
+                return;
+            }
+            var sp = selPortal.transform.position;
+            float radius = new Vector2(sp.x - center.x, sp.z - center.z).magnitude;
+            float y = sp.y;
+            if (radius < 0.5f)
+            {
+                EditorUtility.DisplayDialog("Fix Hub Portals",
+                    "选中的门离圆心太近了，半径几乎为 0。请把它拖到目标圆环上再运行。\n" +
+                    "The selected portal is almost at the centre — drag it out onto the ring first.", "OK");
+                return;
+            }
+
+            // Order portals by era so colours map to the right destination; place China at the top
+            // vertex, the rest clockwise.
+            var byScene = new Dictionary<string, Portal>();
+            foreach (var p in portals)
+            {
+                string scene = ReadTargetScene(p);
+                if (!string.IsNullOrEmpty(scene)) byScene[scene] = p;
+            }
+
+            int placed = 0;
+            for (int i = 0; i < Eras.Length; i++)
+            {
+                if (!byScene.TryGetValue(Eras[i].scene, out var portal) || portal == null) continue;
+
+                // Pentagon vertex, starting due north (top) and going clockwise.
+                float ang = i * 72f * Mathf.Deg2Rad;
+                Vector3 pos = center + new Vector3(Mathf.Sin(ang) * radius, y, Mathf.Cos(ang) * radius);
+
+                Undo.RecordObject(portal.transform, "Fix Hub Portals");
+                portal.transform.position = pos;
+                Vector3 look = center - pos; look.y = 0f;
+                if (look.sqrMagnitude > 0.001f)
+                    portal.transform.rotation = Quaternion.LookRotation(look);
+
+                ApplyColor(portal, Eras[i].color);
+                placed++;
+            }
+
+            // Persist material assets, then save the scene itself (so the transforms / material
+            // assignments / light colours actually hit disk — don't rely on the user pressing Ctrl+S).
+            AssetDatabase.SaveAssets();
+            var activeScene = UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();
+            UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(activeScene);
+            UnityEditor.SceneManagement.EditorSceneManager.SaveScene(activeScene);
+
+            Debug.Log($"[HubPortalFix] placed {placed}/5 portals in a pentagon at radius {radius:F2} " +
+                      $"around {center}; assigned distinct era colours; scene saved.");
+            EditorUtility.DisplayDialog("Fix Hub Portals",
+                $"已把 {placed}/5 个传送阵排成五边形（半径 {radius:F2}）并上色，场景已自动保存。", "OK");
+        }
+
+        [MenuItem("ChronoTraveler/Content/Fix Hub Floor & Spawn (after rescaling)")]

