diff --git a/ChronoTraveler/Assets/Scripts/UI/MemoryHUD.cs b/ChronoTraveler/Assets/Scripts/UI/MemoryHUD.cs
new file mode 100644
index 0000000..ea9a02c
--- /dev/null
+++ b/ChronoTraveler/Assets/Scripts/UI/MemoryHUD.cs
@@ -0,0 +1,219 @@
+using TMPro;
+using UnityEngine;
+using UnityEngine.UI;
+using ChronoTraveler.Core;    // MemoryProgress / SceneFlowManager / GameManager / AudioManager
+using ChronoTraveler.Battle;  // UITheme
+
+namespace ChronoTraveler.UI
+{
+    /// <summary>
+    /// Self-building "记忆修复 / Memory" bar (top-left). Shows the CURRENT map's memory
+    /// restoration 0–100% — the core era-progress metric and Boss gate, previously invisible.
+    /// Subscribes to MemoryProgress; floats a "+N 记忆" toast and pulses on each gain (so
+    /// purging an anomaly is no longer silent); flashes a ScreenBanner when memory hits full.
+    /// Self-boots + DDOL; hidden when the current map has no memory target or while not exploring.
+    /// </summary>
+    public class MemoryHUD : MonoBehaviour
+    {
+        public static MemoryHUD Instance { get; private set; }
+
+        private static readonly Color MemoryTint = new Color32(0x6F, 0xD9, 0xE0, 0xFF); // memory cyan
+
+        private CanvasGroup group;
+        private RectTransform fill;
+        private Image fillImage;
+        private TextMeshProUGUI label;
+        private TextMeshProUGUI toast;
+        private RectTransform toastRt;
+
+        private float shownFill;     // displayed (lerps toward target)
+        private float targetFill;
+        private float lastNorm;
+        private float pulse;         // 0..1 decay for the gain flash
+        private float toastTimer;    // >0 while a toast is animating
+        private bool hasTarget;
+        private bool subMem, subFlow;
+        private AudioClip gainSfx;
+
+        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
+        private static void Bootstrap()
+        {
+            if (Instance == null) new GameObject("[MemoryHUD]").AddComponent<MemoryHUD>();
+        }
+
+        private void Awake()
+        {
+            if (Instance != null && Instance != this) { Destroy(gameObject); return; }
+            Instance = this;
+            DontDestroyOnLoad(gameObject);
+            gainSfx = Resources.Load<AudioClip>("Audio/SFX/itemGet");
+            Build();
+        }
+
+        // Self-boots BeforeSceneLoad, so the managers may not exist yet at Awake/OnEnable.
+        // Wire up lazily in Update until both are available (cheap, stops once subscribed).
+        private void TryWire()
+        {
+            if (!subMem && MemoryProgress.Instance != null)
+            {
+                MemoryProgress.Instance.OnMemoryChanged += OnMemoryChanged;
+                MemoryProgress.Instance.OnMemoryFull += OnMemoryFull;
+                subMem = true;
+                RefreshForCurrentMap();
+            }
+            if (!subFlow && SceneFlowManager.Instance != null)
+            {
+                SceneFlowManager.Instance.OnMapEntered += OnMapEntered;
+                subFlow = true;
+            }
+        }
+
+        private void OnDestroy()
+        {
+            if (MemoryProgress.Instance != null)
+            {
+                MemoryProgress.Instance.OnMemoryChanged -= OnMemoryChanged;
+                MemoryProgress.Instance.OnMemoryFull -= OnMemoryFull;
+            }
+            if (SceneFlowManager.Instance != null)
+                SceneFlowManager.Instance.OnMapEntered -= OnMapEntered;
+        }
+
+        // ---- events ----
+
+        private void OnMapEntered(string mapScene) => RefreshForCurrentMap();
+
+        private void OnMemoryChanged(string mapScene, float norm)
+        {
+            if (SceneFlowManager.Instance == null || mapScene != SceneFlowManager.Instance.CurrentMapScene) return;
+
+            targetFill = norm;
+            int target = MemoryProgress.Instance != null ? MemoryProgress.Instance.TargetFor(mapScene) : 0;
+            int gained = Mathf.RoundToInt(Mathf.Max(0f, norm - lastNorm) * target);
+            lastNorm = norm;
+
+            if (gained > 0)
+            {
+                pulse = 1f;
+                ShowToast($"+{gained} 记忆");
+                if (gainSfx != null && AudioManager.Instance != null) AudioManager.Instance.PlaySFX(gainSfx);
+            }
+        }

