@@ -0,0 +1,173 @@
+using UnityEngine;
+using ChronoTraveler.Core;          // SceneFlowManager / GameManager / GameState
+using ChronoTraveler.Quest;         // QuestManager / ObjectiveType / quest data
+using ChronoTraveler.NPC;           // NPCController
+using ChronoTraveler.Collectibles;  // CollectibleItem
+
+namespace ChronoTraveler.World
+{
+    /// <summary>
+    /// Objective waypoint: resolves the current quest objective's world target and marks it
+    /// with a glowing pillar + bobbing diamond + a ground disc. The top-down minimap camera
+    /// renders the disc automatically, so the same beacon doubles as the minimap blip — no
+    /// minimap code needed. Self-boots + DDOL; re-evaluates on quest updates and on a short
+    /// timer (new map objects). Hidden when there is no active objective or while not exploring.
+    /// </summary>
+    public class WaypointSystem : MonoBehaviour
+    {
+        public static WaypointSystem Instance { get; private set; }
+
+        private static readonly Color Marker = new Color32(0xF0, 0xCE, 0x77, 0xFF); // objective gold
+
+        private GameObject beacon;
+        private Transform pillar, disc, diamond;
+        private float refreshTimer;
+        private bool subQuest;
+
+        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
+        private static void Bootstrap()
+        {
+            if (Instance == null) new GameObject("[WaypointSystem]").AddComponent<WaypointSystem>();
+        }
+
+        private void Awake()
+        {
+            if (Instance != null && Instance != this) { Destroy(gameObject); return; }
+            Instance = this;
+            DontDestroyOnLoad(gameObject);
+            BuildBeacon();
+        }
+
+        private void OnDestroy()
+        {
+            if (QuestManager.Instance != null) QuestManager.Instance.OnQuestUpdated -= OnQuestUpdated;
+        }
+
+        private void TryWire()
+        {
+            if (subQuest || QuestManager.Instance == null) return;
+            QuestManager.Instance.OnQuestUpdated += OnQuestUpdated;
+            subQuest = true;
+        }
+
+        private void OnQuestUpdated() => refreshTimer = 0f;   // re-resolve promptly when objectives change
+
+        private void Update()
+        {
+            if (!subQuest) TryWire();
+
+            // Animate the floating diamond (bob + spin) when visible.
+            if (beacon.activeSelf && diamond != null)
+            {
+                float bob = Mathf.Sin(Time.time * 2.2f) * 0.25f;
+                diamond.localPosition = new Vector3(0f, 6.0f + bob, 0f);
+                diamond.Rotate(0f, 90f * Time.deltaTime, 0f, Space.Self);
+            }
+
+            refreshTimer -= Time.deltaTime;
+            if (refreshTimer <= 0f) { refreshTimer = 0.3f; Resolve(); }
+        }
+
+        private void Resolve()
+        {
+            bool exploring = GameManager.Instance == null || GameManager.Instance.CurrentState == GameState.Exploring;
+            Transform target = exploring ? ResolveTarget() : null;
+
+            if (target == null) { if (beacon.activeSelf) beacon.SetActive(false); return; }
+
+            beacon.transform.position = target.position;
+            if (!beacon.activeSelf) beacon.SetActive(true);
+        }
+
+        /// <summary>The world transform of the current stage's first incomplete objective, or null.</summary>
+        private Transform ResolveTarget()
+        {
+            var qm = QuestManager.Instance;
+            var rt = qm != null ? qm.CurrentQuest() : null;
+            var def = qm != null ? qm.CurrentDef() : null;
+            if (rt == null || def == null || rt.completed) return null;
+            if (rt.stageIndex < 0 || rt.stageIndex >= def.stages.Count) return null;
+
+            var stage = def.stages[rt.stageIndex];
+            for (int i = 0; i < stage.objectives.Count; i++)
+            {
+                int cur = i < rt.progress.Count ? rt.progress[i] : 0;
+                var o = stage.objectives[i];
+                if (cur >= o.required) continue;        // done — skip to next objective
+
+                switch (o.type)
+                {
+                    case ObjectiveType.TalkTo: return FindNpc(o.targetId);
+                    case ObjectiveType.Defeat: return FindAnomaly(o.targetId);
+                    case ObjectiveType.Collect: return FindFragment(o.targetId);
+                    case ObjectiveType.ReachMemory: return null; // covered by the memory bar, no world point
+                }

