diff --git a/ChronoTraveler/Assets/Scripts/World/EnvironmentPostFX.cs b/ChronoTraveler/Assets/Scripts/World/EnvironmentPostFX.cs
new file mode 100644
index 0000000..77351e7
--- /dev/null
+++ b/ChronoTraveler/Assets/Scripts/World/EnvironmentPostFX.cs
@@ -0,0 +1,69 @@
+using UnityEngine;
+using UnityEngine.Rendering;
+using UnityEngine.Rendering.Universal;
+
+namespace ChronoTraveler.World
+{
+    /// <summary>
+    /// Runtime cinematic post-processing (Environment track · advanced VFX): builds a global URP Volume
+    /// with Bloom + Color Adjustments + Vignette, and turns ON post-processing on the main camera in
+    /// code — so it's zero manual setup. Bloom makes the sea sheen, sun glints and memory motes glow;
+    /// the colour grade + vignette add a filmic feel. Self-builds at runtime. Tune the values in the
+    /// Inspector fields below; they apply at Start.
+    /// </summary>
+    [DisallowMultipleComponent]
+    public class EnvironmentPostFX : MonoBehaviour
+    {
+        [Header("Bloom")]
+        public float bloomIntensity = 0.85f;
+        public float bloomThreshold = 1.0f;
+        public Color bloomTint = new Color(1f, 0.97f, 0.9f);
+
+        [Header("Color grade")]
+        public float postExposure = 0.08f;
+        public float contrast = 8f;
+        public float saturation = 6f;
+
+        [Header("Vignette")]
+        public float vignetteIntensity = 0.26f;
+        public float vignetteSmoothness = 0.4f;
+
+        private void Start()
+        {
+            EnableCameraPostProcessing();
+            BuildVolume();
+        }
+
+        private void EnableCameraPostProcessing()
+        {
+            var cam = Camera.main;
+            if (cam == null) return;
+            var data = cam.GetUniversalAdditionalCameraData();
+            if (data != null) data.renderPostProcessing = true;   // no manual checkbox needed
+        }
+
+        private void BuildVolume()
+        {
+            var vol = gameObject.AddComponent<Volume>();
+            vol.isGlobal = true;
+            vol.priority = 1f;
+
+            var profile = ScriptableObject.CreateInstance<VolumeProfile>();
+            vol.sharedProfile = profile;
+
+            var bloom = profile.Add<Bloom>(true);
+            bloom.intensity.Override(Mathf.Max(0f, bloomIntensity));
+            bloom.threshold.Override(Mathf.Max(0f, bloomThreshold));
+            bloom.tint.Override(bloomTint);
+
+            var grade = profile.Add<ColorAdjustments>(true);
+            grade.postExposure.Override(postExposure);
+            grade.contrast.Override(contrast);
+            grade.saturation.Override(saturation);
+
+            var vig = profile.Add<Vignette>(true);
+            vig.intensity.Override(Mathf.Clamp01(vignetteIntensity));
+            vig.smoothness.Override(Mathf.Clamp01(vignetteSmoothness));
+        }
+    }
+}

