             var rt = new QuestRuntime { questId = questId, stageIndex = 0, completed = false };
-            ResetStageProgress(rt);
             actives.Add(rt);
+            EnterCurrentStage(rt);   // backfills from world state in case things were done out of order
             Debug.Log($"[QuestManager] started quest '{questId}'.");
             OnQuestUpdated?.Invoke();
@@ -171,5 +172,66 @@ namespace ChronoTraveler.Quest
                 OnQuestCompleted?.Invoke(def);
             }
-            else ResetStageProgress(rt);
+            else EnterCurrentStage(rt);   // backfill the new stage too (chains through anything already done)
+        }
+
+        /// <summary>
+        /// Enter the current stage: reset its progress, then BACKFILL from persistent world state
+        /// (collected fragments / purged encounters / talked NPCs / full memory). This is what makes
+        /// out-of-order play safe — even though the world object was consumed and destroyed, the RECORD
+        /// of it persists (CollectionManager / SaveManager / MemoryProgress), so a stage that activates
+        /// after the player already did its objective auto-completes instead of dead-locking.
+        /// </summary>
+        private void EnterCurrentStage(QuestRuntime rt)
+        {
+            var def = DefOf(rt);
+            ResetStageProgress(rt);
+            if (def == null || rt.stageIndex >= def.stages.Count) return;
+            BackfillStage(rt, def);
+            if (StageComplete(rt, def.stages[rt.stageIndex])) AdvanceStage(rt, def);
+        }
+
+        private void BackfillStage(QuestRuntime rt, QuestDefinition def)
+        {
+            var stage = def.stages[rt.stageIndex];
+            for (int i = 0; i < stage.objectives.Count && i < rt.progress.Count; i++)
+            {
+                int have = CountSatisfied(stage.objectives[i]);
+                if (have > rt.progress[i]) rt.progress[i] = Mathf.Min(have, stage.objectives[i].required);
+            }
+        }
+
+        /// <summary>How much of an objective is ALREADY satisfied by persisted world state.</summary>
+        private int CountSatisfied(QuestObjective obj)
+        {
+            switch (obj.type)
+            {
+                case ObjectiveType.Collect:
+                    var cm = CollectionManager.Instance;
+                    if (cm == null) return 0;
+                    int c = 0;
+                    foreach (var id in cm.GetCollectedIds()) if (MatchesCollect(obj, id)) c++;
+                    return c;
+                case ObjectiveType.Defeat:
+                    if (string.IsNullOrEmpty(obj.targetId) || obj.targetId == "any") return 0;
+                    return (SaveManager.Instance != null && SaveManager.Instance.IsEncounterPurged(obj.targetId)) ? obj.required : 0;
+                case ObjectiveType.TalkTo:
+                    if (string.IsNullOrEmpty(obj.targetId) || obj.targetId == "any") return 0;
+                    foreach (var npc in FindObjectsByType<NPCController>(FindObjectsSortMode.None))
+                        if (npc != null && npc.NPCID == obj.targetId && npc.HasBeenTalkedTo) return obj.required;
+                    return 0;
+                case ObjectiveType.ReachMemory:
+                    var mp = MemoryProgress.Instance;
+                    string map = string.IsNullOrEmpty(obj.targetId) || obj.targetId == "any"
+                        ? (SceneFlowManager.Instance != null ? SceneFlowManager.Instance.CurrentMapScene : null)
+                        : obj.targetId;
+                    return (mp != null && !string.IsNullOrEmpty(map) && mp.IsFull(map)) ? obj.required : 0;
+                default: return 0;
+            }
+        }
+
+        private static bool MatchesCollect(QuestObjective obj, string id)
+        {
+            if (string.IsNullOrEmpty(obj.targetId) || obj.targetId == "any") return true;
+            return id != null && id.StartsWith(obj.targetId);
         }

