+using System.Collections.Generic;
+using UnityEngine;
+using UnityEngine.Rendering;
+
+namespace ChronoTraveler.Effects
+{
+    /// <summary>
+    /// Code-generated "premium prop" visuals — procedural textures, meshes and additive
+    /// materials for magic-flavoured world objects (portals, memory-fragment crystals).
+    /// Same philosophy as EnvironmentBackdrop / StylizedWater: zero art assets, zero manual
+    /// steps; textures are drawn once and cached. Deliberately NOT 3D-modelled — these
+    /// objects read through glow/motion/texture, which is shader-and-particle territory,
+    /// and it keeps their look consistent with the procedural anomaly visual language.
+    /// </summary>
+    public static class PropVisuals
+    {
+        private static Texture2D runeTex, swirlTex, beamTex, dotTex;
+        private static Material particleMat;
+
+        /// <summary>Additive URP particle material with a soft radial dot — replaces the
+        /// built-in-pipeline "Particles/Standard Unlit" (magenta/degraded under URP) for all
+        /// ParticleEffectFactory systems. Cached; falls back gracefully outside URP.</summary>
+        public static Material ParticleAdditiveMaterial()
+        {
+            if (particleMat != null) return particleMat;
+            var sh = Shader.Find("Universal Render Pipeline/Particles/Unlit");
+            if (sh == null) sh = Shader.Find("Particles/Standard Unlit");
+            if (sh == null) sh = Shader.Find("Sprites/Default");
+            var m = new Material(sh);
+            if (m.HasProperty("_BaseMap")) m.SetTexture("_BaseMap", SoftDotTexture());
+            else m.mainTexture = SoftDotTexture();
+            if (m.HasProperty("_BaseColor")) m.SetColor("_BaseColor", Color.white);
+            if (m.HasProperty("_Surface"))
+            {
+                m.SetFloat("_Surface", 1f);
+                m.SetFloat("_Blend", 2f);
+                m.SetFloat("_SrcBlend", (float)BlendMode.SrcAlpha);
+                m.SetFloat("_DstBlend", (float)BlendMode.One);
+                m.SetFloat("_ZWrite", 0f);
+                m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
+                m.SetOverrideTag("RenderType", "Transparent");
+                m.renderQueue = (int)RenderQueue.Transparent;
+            }
+            particleMat = m;
+            return m;
+        }
+
+        /// <summary>64×64 soft radial falloff — the particle "spark" sprite.</summary>
+        public static Texture2D SoftDotTexture()

