+using UnityEngine;
+using ChronoTraveler.Core;
+
+namespace ChronoTraveler.World
+{
+    /// <summary>
+    /// Safety net for walking off a map's edge (Egypt's temple floats over the sand-sea; other
+    /// eras have their own drops). Falling far below the map's spawn level teleports the player
+    /// back to the spawn point with a Xuanji rescue bark — deliberately NOT death: the game's
+    /// defeat philosophy is gentle learn-and-retry, and a hazard-respawn (Hollow Knight style,
+    /// minus the damage) turns a boundary bug into a character moment. Created per era map by
+    /// EnvironmentBootstrap; lives in the map scene so it unloads with it.
+    /// </summary>
+    [DisallowMultipleComponent]
+    public class FallRescue : MonoBehaviour
+    {
+        public float fallDistance = 45f;   // metres below the lowest spawn before the rescue fires
+
+        private Transform player;
+        private float rescueY;
+        private bool calibrated;
+        private float cooldownUntil;
+
+        private void Update()
+        {
+            if (!calibrated) { Calibrate(); return; }
+            if (Time.time < cooldownUntil) return;
+
+            if (player == null)
+            {
+                var p = GameObject.FindGameObjectWithTag("Player");
+                if (p == null) return;
+                player = p.transform;
+            }
+
+            if (player.position.y < rescueY) Rescue();
+        }
+
+        private void Calibrate()
+        {
+            float lowest = float.PositiveInfinity;
+            foreach (var sp in Object.FindObjectsByType<SpawnPoint>(FindObjectsSortMode.None))
+                if (sp.gameObject.scene == gameObject.scene)
+                    lowest = Mathf.Min(lowest, sp.transform.position.y);
+            if (float.IsPositiveInfinity(lowest)) return;   // spawns not loaded yet — retry next frame
+            rescueY = lowest - fallDistance;
+            calibrated = true;
+        }
+
+        private void Rescue()
+        {
+            cooldownUntil = Time.time + 2f;

