+        /// sequence. This chain is the game's macro-structure: each starstone wakes the next gate.</summary>
+        public static readonly string[] EraOrder = { "china", "egypt", "greece", "rome", "trade" };
+
+        /// <summary>An era is unlocked when it is the FIRST era, or the previous era's starstone
+        /// has been earned. <paramref name="hasToken"/> is injected (EraProgress supplies it at
+        /// runtime) so the rule stays engine-free and unit-testable. Unknown eras are locked.</summary>
+        public static bool IsEraUnlocked(string mapId, Func<string, bool> hasToken)
+        {
+            if (string.IsNullOrEmpty(mapId) || hasToken == null) return false;
+            int i = Array.IndexOf(EraOrder, mapId.ToLowerInvariant());
+            if (i < 0) return false;
+            if (i == 0) return true;
+            return hasToken(EraOrder[i - 1]);
+        }
+
+        /// <summary>The era whose gate wakes after earning <paramref name="mapId"/>'s starstone
+        /// (null at the end of the chain or for unknown eras).</summary>
+        public static string NextEra(string mapId)
+        {
+            if (string.IsNullOrEmpty(mapId)) return null;
+            int i = Array.IndexOf(EraOrder, mapId.ToLowerInvariant());
+            return i >= 0 && i + 1 < EraOrder.Length ? EraOrder[i + 1] : null;
+        }
