+using UnityEngine;
+
+namespace ChronoTraveler.Core
+{
+    /// <summary>
+    /// Dev-only demo hotkeys for recording the dissertation video (and quick testing) —
+    /// active ONLY in the editor or a Development Build, a no-op in release. Self-boots.
+    ///
+    ///   F9  — award the next un-earned era starstone (in order). Press in the hub to stage
+    ///         the star-wake moment on camera without replaying an era.
+    ///   F10 — complete the CURRENT map's collectibles + fill its memory (opens the boss gate
+    ///         instantly, so a boss take needs no fragment hunt).
+    /// </summary>
+    public class DemoTools : MonoBehaviour
+    {
+        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
+        private static void Bootstrap()
+        {
+            if (!Application.isEditor && !Debug.isDebugBuild) return;   // release builds: never exists
+            new GameObject("[DemoTools]").AddComponent<DemoTools>().gameObject
+                .transform.SetParent(null);
+        }
+
+        private void Awake() => DontDestroyOnLoad(gameObject);
+
+        private void Update()
+        {
+            if (Input.GetKeyDown(KeyCode.F9)) AwardNextToken();
+            if (Input.GetKeyDown(KeyCode.F10)) CompleteCurrentMap();
+        }
+
+        private static void AwardNextToken()
+        {
+            if (EraProgress.Instance == null) return;
+            foreach (var era in EraCompletion.EraOrder)
+            {
+                if (EraProgress.Instance.HasToken(era)) continue;
+                EraProgress.Instance.AwardToken(era);
+                Debug.Log($"[DemoTools] F9 → starstone awarded: {era} " +
+                          "(revisit the hub to see the next gate wake).");
+                return;
+            }
+            Debug.Log("[DemoTools] F9 → all starstones already earned.");
+        }
+
+        private static void CompleteCurrentMap()
+        {
+            string map = SceneFlowManager.Instance != null ? SceneFlowManager.Instance.CurrentMapScene : null;
+            if (string.IsNullOrEmpty(map)) { Debug.Log("[DemoTools] F10 → no map loaded."); return; }
+
+            var player = GameObject.FindGameObjectWithTag("Player");
+            int picked = 0;
+            foreach (var item in Object.FindObjectsByType<Collectibles.CollectibleItem>(FindObjectsSortMode.None))
+                if (!item.Collected && player != null) { item.Interact(player); picked++; }
+
+            MemoryProgress.Instance?.AddMemory(map, 999);
+            Debug.Log($"[DemoTools] F10 → {picked} collectibles gathered + memory filled on '{map}' (boss gate open).");
+        }
+    }
+}
