diff --git a/ChronoTraveler/Assets/Editor/BuildPrepTool.cs b/ChronoTraveler/Assets/Editor/BuildPrepTool.cs
new file mode 100644
index 0000000..8dcb7c9
--- /dev/null
+++ b/ChronoTraveler/Assets/Editor/BuildPrepTool.cs
@@ -0,0 +1,81 @@
+using System.Collections.Generic;
+using UnityEditor;
+using UnityEngine;
+using UnityEngine.Rendering;
+
+namespace ChronoTraveler.EditorTools
+{
+    /// <summary>
+    /// One-click pre-build hardening: menu ChronoTraveler/Build/Prepare Build.
+    /// The game creates several materials at RUNTIME via Shader.Find — those shaders are
+    /// referenced by no asset, so Unity strips them from builds (ocean invisible, particles
+    /// magenta, procedural sky black — a known debt item). This adds them to Graphics
+    /// Settings' Always Included Shaders (idempotent) and sanity-checks the scene list.
+    /// Run once before the first build and after adding new runtime shaders.
+    /// </summary>
+    public static class BuildPrepTool
+    {
+        // Every shader the code base resolves via Shader.Find at runtime.
+        private static readonly string[] RuntimeShaders =
+        {
+            "ChronoTraveler/StylizedWater",       // OceanIsland water
+            "ChronoTraveler/Anomaly",             // anomaly orb visual
+            "ChronoTraveler/ToonURP",             // toon material fallback
+            "Universal Render Pipeline/Unlit",    // PropVisuals additive quads, backdrop
+            "Universal Render Pipeline/Lit",      // runtime-created materials everywhere
+            "Universal Render Pipeline/Particles/Unlit",   // ParticleAdditiveMaterial
+            "Skybox/Procedural",                  // EraAtmosphere generated skies
+            "Sprites/Default",                    // companion sprite, fallbacks
+        };
+
+        [MenuItem("ChronoTraveler/Build/Prepare Build (always-include shaders + checks)")]
+        public static void Prepare()
+        {
+            AddAlwaysIncludedShaders();
+            CheckBuildScenes();
+            Debug.Log("[BuildPrep] done — safe to File > Build.");
+        }
+
+        private static void AddAlwaysIncludedShaders()
+        {
+            var gs = AssetDatabase.LoadAssetAtPath<Object>("ProjectSettings/GraphicsSettings.asset");
+            if (gs == null) { Debug.LogError("[BuildPrep] GraphicsSettings.asset not found."); return; }
+
+            var so = new SerializedObject(gs);
+            var arr = so.FindProperty("m_AlwaysIncludedShaders");
+            var existing = new HashSet<Shader>();
+            for (int i = 0; i < arr.arraySize; i++)
+            {
+                var s = arr.GetArrayElementAtIndex(i).objectReferenceValue as Shader;
+                if (s != null) existing.Add(s);
+            }
+
+            int added = 0;
+            foreach (var name in RuntimeShaders)
+            {
+                var shader = Shader.Find(name);
+                if (shader == null) { Debug.LogWarning($"[BuildPrep] shader not found: {name}"); continue; }
+                if (existing.Contains(shader)) continue;
+                arr.InsertArrayElementAtIndex(arr.arraySize);
+                arr.GetArrayElementAtIndex(arr.arraySize - 1).objectReferenceValue = shader;
+                existing.Add(shader);
+                added++;
+                Debug.Log($"[BuildPrep] always-include: {name}");
+            }
+            so.ApplyModifiedPropertiesWithoutUndo();
+            AssetDatabase.SaveAssets();
+            Debug.Log($"[BuildPrep] Always Included Shaders: +{added} (total {arr.arraySize}).");
+        }
+
+        private static void CheckBuildScenes()
+        {
+            int enabled = 0;
+            foreach (var s in EditorBuildSettings.scenes) if (s.enabled) enabled++;
+            if (enabled < 7)
+                Debug.LogWarning($"[BuildPrep] only {enabled} scenes enabled in Build Settings (expected 7: " +
+                                 "MainScene + Hub + 5 eras). File > Build Settings to verify.");
+            else
+                Debug.Log($"[BuildPrep] Build Settings: {enabled} scenes enabled ✓");
+        }
+    }
+}
