+using System.Collections;
+using UnityEngine;
+using ChronoTraveler.Core;
+
+namespace ChronoTraveler.Cutscene
+{
+    /// <summary>
+    /// Plays StreamingAssets/Videos/opening.mp4 fullscreen over the main menu at boot —
+    /// the galgame/anime-game opening movie slot. Once per app run, any key skips,
+    /// absent file = silent no-op. Title BGM pauses under the movie's own audio.
+    /// </summary>
+    public class OpeningVideoGate : MonoBehaviour
+    {
+        private const string FileName = "opening.mp4";
+        private static bool playedThisRun;
+
+        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]
+        private static void Bootstrap()
+        {
+            if (!playedThisRun && VideoGate.HasVideo(FileName))
+                new GameObject("[OpeningVideoGate]").AddComponent<OpeningVideoGate>();
+        }
+
+        private IEnumerator Start()
+        {
+            playedThisRun = true;
+            yield return null;   // let the menu and managers finish their first frame
+            AudioManager.Instance?.PauseBGM(true);
+            yield return VideoGate.Play(FileName);
+            AudioManager.Instance?.PauseBGM(false);
+            Destroy(gameObject);
+        }
+    }
+}
