+++ b/ChronoTraveler/Assets/Scripts/UI/TitleScreenSkin.cs
@@ -0,0 +1,508 @@
+using System.Collections;
+using System.Collections.Generic;
+using TMPro;
+using UnityEngine;
+using UnityEngine.EventSystems;
+using UnityEngine.UI;
+using ChronoTraveler.Core;
+
+namespace ChronoTraveler.UI
+{
+    /// <summary>
+    /// Galgame-style title screen dressing: fullscreen key art with a slow Ken Burns drift,
+    /// a left gradient scrim carrying a vertical menu column (hover glow + cascade slide-in),
+    /// drifting star dust, and save info under Continue. Built entirely at runtime when
+    /// Resources/UI/title_keyart exists; without the art the legacy scene menu is untouched,
+    /// so the title look never blocks on the asset (same philosophy as VideoGate).
+    /// Everything animates on unscaled time — the menu freezes Time.timeScale.
+    /// </summary>
+    public static class TitleScreenSkin
+    {
+        public const string KeyArtPath = "UI/title_keyart";
+
+        /// <summary>Apply the skin over the scene menu. Returns null (legacy menu kept) when
+        /// the key art asset is missing. New entries re-invoke the original buttons' onClick,
+        /// so all MainMenuUI logic (save gating, video gate, quit) stays in one place.</summary>
+        public static Controller TryApply(GameObject menuPanel,
+                                          Button startButton, Button continueButton, Button quitButton,
+                                          TMP_Text oldTitle, TMP_Text oldSubtitle)
+        {
+            if (menuPanel == null) return null;
+            var art = Resources.Load<Sprite>(KeyArtPath);
+            if (art == null) return null;
+
+            // Retire the legacy centered layout (objects stay for logic; visuals go).
+            bool hasSave = continueButton != null && continueButton.gameObject.activeSelf;
+            if (oldTitle != null) oldTitle.gameObject.SetActive(false);
+            if (oldSubtitle != null) oldSubtitle.gameObject.SetActive(false);
+            if (startButton != null) startButton.gameObject.SetActive(false);
+            if (continueButton != null) continueButton.gameObject.SetActive(false);
+            if (quitButton != null) quitButton.gameObject.SetActive(false);
+            var version = menuPanel.transform.Find("VersionText");
+            if (version != null) version.gameObject.SetActive(false);
+            var panelImage = menuPanel.GetComponent<Image>();
+            if (panelImage != null) panelImage.enabled = false;   // key art replaces the dark slab
+
+            var host = new GameObject("TitleSkin", typeof(RectTransform));
+            host.transform.SetParent(menuPanel.transform, false);
+            host.transform.SetAsFirstSibling();   // behind LanguageToggle and any later overlays
+            Stretch(host.GetComponent<RectTransform>());
+
+            var ctrl = host.AddComponent<Controller>();
+            ctrl.Build(art, hasSave, startButton, continueButton, quitButton);
+            return ctrl;

