+using UnityEditor;
+using UnityEditor.SceneManagement;
+using UnityEngine;
+using UnityEngine.UI;
+
+namespace ChronoTraveler.EditorTools
+{
+    /// <summary>
+    /// Bakes the title-screen look into the open scene for EDIT MODE: hides the legacy
+    /// centered menu visuals and drops the key art in as a background, so the Game view
+    /// matches what TitleScreenSkin builds at runtime. The runtime skin detects the
+    /// "TitleKeyArtPreview" object and replaces it with the full interactive stack.
+    /// Run from: ChronoTraveler → UI → Title · Apply Edit-Mode Preview (then save the scene).
+    /// </summary>
+    public static class TitleScreenPreviewTool
+    {
+        private const string PreviewName = "TitleKeyArtPreview";
+        private static readonly string[] LegacyChildren =
+        {
+            "TitleText", "SubtitleText", "StartButton", "ContinueButton", "QuitButton", "VersionText"
+        };
+
+        [MenuItem("ChronoTraveler/UI/Title · Apply Edit-Mode Preview")]
+        public static void Apply()
+        {
+            var panel = GameObject.Find("MainMenuPanel");
+            if (panel == null)
+            {
+                EditorUtility.DisplayDialog("Title Preview",
+                    "MainMenuPanel not found — open MainScene (the Core scene) first.", "OK");
+                return;
+            }
+
+            var art = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Resources/UI/title_keyart.png");
+            if (art == null)
+            {
+                EditorUtility.DisplayDialog("Title Preview",
+                    "Assets/Resources/UI/title_keyart.png did not import as a Sprite.", "OK");
+                return;
+            }
+
+            Undo.RegisterFullObjectHierarchyUndo(panel, "Apply Title Preview");
+
+            // hide the legacy centered layout (runtime logic still uses these objects)
+            foreach (var name in LegacyChildren)
+            {
+                var t = panel.transform.Find(name);
+                if (t != null) t.gameObject.SetActive(false);
+            }
+
+            // the dark slab is replaced by the art
+            var panelImage = panel.GetComponent<Image>();
+            if (panelImage != null) panelImage.enabled = false;
+
+            // key art background (recreated to pick up an updated sprite on re-run)
+            var old = panel.transform.Find(PreviewName);
+            if (old != null) Undo.DestroyObjectImmediate(old.gameObject);
+
+            var go = new GameObject(PreviewName, typeof(RectTransform));
+            Undo.RegisterCreatedObjectUndo(go, "Apply Title Preview");
+            go.transform.SetParent(panel.transform, false);
+            go.transform.SetAsFirstSibling();
+            var rt = (RectTransform)go.transform;
+            rt.anchorMin = Vector2.zero;
+            rt.anchorMax = Vector2.one;
+            rt.offsetMin = Vector2.zero;
+            rt.offsetMax = Vector2.zero;
+            var img = go.AddComponent<Image>();
+            img.sprite = art;
+            img.raycastTarget = false;
+            var fitter = go.AddComponent<AspectRatioFitter>();
+            fitter.aspectMode = AspectRatioFitter.AspectMode.EnvelopeParent;
+            fitter.aspectRatio = art.rect.width / Mathf.Max(1f, art.rect.height);
+
+            EditorSceneManager.MarkSceneDirty(panel.scene);
+            Debug.Log("[TitleScreenPreviewTool] Edit-mode title preview applied — save the scene (Ctrl+S).");
+        }
+    }
+}
