diff --git a/ChronoTraveler/Assets/Editor/EraBuildEngine.cs b/ChronoTraveler/Assets/Editor/EraBuildEngine.cs
new file mode 100644
index 0000000..c5cfed1
--- /dev/null
+++ b/ChronoTraveler/Assets/Editor/EraBuildEngine.cs
@@ -0,0 +1,315 @@
+using System.Collections.Generic;
+using System.IO;
+using UnityEditor;
+using UnityEditor.SceneManagement;
+using UnityEngine;
+using ChronoTraveler.Battle;
+using ChronoTraveler.World;
+using ChronoTraveler.NPC;
+using ChronoTraveler.Core;
+using ChronoTraveler.Collectibles;
+
+namespace ChronoTraveler.EditorTools
+{
+    /// <summary>
+    /// Shared era-building engine, extracted 1:1 from the battle-tested Egypt path
+    /// (EgyptContentSetupTool stays frozen as the historical artifact). Adds the
+    /// procedural-ground mode so an era is playable BEFORE its asset pack arrives;
+    /// re-running with a demo scene later swaps the environment while user-tuned
+    /// object positions survive (TryReadPreviousLayout).
+    /// </summary>
+    public static class EraBuildEngine
+    {
+        public const float MaxStep = 0.75f;   // single jump: same floor level or unreachable
+        public const string ProceduralGroundName = "[ProceduralGround]";
+
+        // ---- demo-scene prep ----------------------------------------------------------
+
+        public static void StripConflicts<T>() where T : Component
+        {
+            foreach (var comp in Object.FindObjectsByType<T>(FindObjectsSortMode.None))
+                if (comp != null) Object.DestroyImmediate(comp.gameObject);
+        }
+
+        /// <summary>Give every collider-less mesh a MeshCollider so the imported environment
+        /// is walkable and the placement raycast works. Static scenery → non-convex is fine.</summary>
+        public static int AddEnvironmentColliders()
+        {
+            int n = 0;
+            foreach (var mf in Object.FindObjectsByType<MeshFilter>(FindObjectsSortMode.None))
+            {
+                if (mf == null || mf.sharedMesh == null) continue;
+                if (mf.GetComponent<Collider>() != null) continue;
+                var mc = mf.gameObject.AddComponent<MeshCollider>();
+                mc.sharedMesh = mf.sharedMesh;
+                n++;
+            }
+            return n;
+        }
+
+        public static Bounds ContentBounds()
+        {
+            var rends = Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None);
+            if (rends.Length == 0) return new Bounds(Vector3.zero, Vector3.one * 20f);
+            Bounds b = rends[0].bounds;
+            foreach (var r in rends) b.Encapsulate(r.bounds);
+            return b;
+        }
+
+        /// <summary>Parent all roots under one node and scale up (player stays normal-size).
+        /// Run BEFORE placement so bounds/raycast see the scale.</summary>
+        public static void ScaleEnvironment(UnityEngine.SceneManagement.Scene scene, float scale, string rootName)
+        {
+            if (Mathf.Approximately(scale, 1f)) return;
+            var root = new GameObject(rootName);
+            foreach (var go in scene.GetRootGameObjects())
+                if (go != root) go.transform.SetParent(root.transform, true);
+            root.transform.localScale = Vector3.one * scale;
+        }
+
+        public static void ApplyLighting(Color ambient, Color sun, float sunIntensity, float shadowStrength)
+        {
+            RenderSettings.ambientMode = UnityEngine.Rendering.AmbientMode.Flat;
+            RenderSettings.ambientLight = ambient;
+            foreach (var l in Object.FindObjectsByType<Light>(FindObjectsSortMode.None))
+                if (l.type == LightType.Directional)
+                {
+                    l.intensity = Mathf.Max(l.intensity, sunIntensity);
+                    l.shadowStrength = shadowStrength;
+                    l.color = sun;
+                }
+        }
+
+        // ---- procedural mode ----------------------------------------------------------
+
+        /// <summary>No-asset-pack mode: a large flat tinted ground plane (with MeshCollider,
+        /// via the Plane primitive) so the gameplay layer is playable TODAY. Sky/fog/backdrop/
+        /// boundary-rescue come from the runtime systems (EraAtmosphere, EnvironmentBootstrap,
+        /// FallRescue) keyed on mapId — zero manual steps. Idempotent by name.</summary>
+        public static void BuildProceduralGround(Color tint)
+        {
+            if (GameObject.Find(ProceduralGroundName) != null) return;
+            var go = GameObject.CreatePrimitive(PrimitiveType.Plane);   // 10×10 base, has MeshCollider
+            go.name = ProceduralGroundName;
+            go.transform.position = Vector3.zero;
+            go.transform.localScale = Vector3.one * 9f;                 // → 90×90 m
+            var m = new Material(Shader.Find("Universal Render Pipeline/Lit"));
+            m.SetColor("_BaseColor", tint);
+            go.GetComponent<MeshRenderer>().sharedMaterial = m;
+        }
+
+        // ---- layout persistence -------------------------------------------------------
+
+        /// <summary>Reads the user-tuned layout from the existing scene so rebuilds keep it:
+        /// spawn transforms + every hand-moved gameplay object. wasProcedural reports whether
+        /// the previous scene was the no-pack mode — switching to a demo pack must NOT reuse
+        /// procedural-world coordinates (different world frame), the caller discards them.</summary>
+        public static bool TryReadPreviousLayout(string scenePath, string[] keptNames,
+                                                 out Vector3 defPos, out Quaternion defRot,
+                                                 out Vector3 hubPos, out Quaternion hubRot,
+                                                 out Dictionary<string, Vector3> kept,
