diff --git a/ChronoTraveler/Assets/Editor/FinaleBossModelTool.cs b/ChronoTraveler/Assets/Editor/FinaleBossModelTool.cs
new file mode 100644
index 0000000..67da0e6
--- /dev/null
+++ b/ChronoTraveler/Assets/Editor/FinaleBossModelTool.cs
@@ -0,0 +1,168 @@
+using System.Collections.Generic;
+using System.IO;
+using System.Linq;
+using UnityEditor;
+using UnityEditor.Animations;
+using UnityEngine;
+
+namespace ChronoTraveler.EditorTools
+{
+    /// <summary>
+    /// Bakes the finale boss trueform from the Hunyuan 3D Studio FBX set (rigged + skinned +
+    /// one animation per file) into a game-ready prefab:
+    ///   Assets/Art/Characters/Finale/boss_{idle,attack,hitdown,leap}.fbx
+    ///   → configure importers (Generic rig, looping idle, extracted textures)
+    ///   → URP/Lit materials (FBX Standard materials render magenta under URP)
+    ///   → AnimatorController (Idle default-loop; attack/hit/leap triggers)
+    ///   → Resources/CharacterModels/finale_boss_trueform.prefab (10m tall, grounded, +Z facing)
+    /// Used by the two-act finale rework: the pinned, EMBODIED boss standing on the platform.
+    /// Idempotent — re-run after replacing any FBX.
+    /// </summary>
+    public static class FinaleBossModelTool
+    {
+        private const string Dir = "Assets/Art/Characters/Finale";
+        private const string TexDir = Dir + "/Textures";
+        private const string MatDir = Dir + "/Materials";
+        private const string CtrlPath = Dir + "/FinaleBossTrueform.controller";
+        private const string PrefabPath = "Assets/Resources/CharacterModels/finale_boss_trueform.prefab";
+        private const float TargetHeight = 10f;   // spec: an 8-12m embodied colossus on the platform
+
+        private static readonly (string file, string state, string trigger, bool loop)[] Anims =
+        {
+            ("boss_idle",    "Idle",    null,     true),
+            ("boss_attack",  "Attack",  "attack", false),
+            ("boss_hitdown", "HitDown", "hit",    false),
+            ("boss_leap",    "Leap",    "leap",   false),
+        };
+
+        [MenuItem("ChronoTraveler/Content/Bake Finale Boss Trueform (FBX → prefab)")]
+        public static void Bake()
+        {
+            // ---- 1) importer pass: Generic rig, loop the idle, pull embedded textures ----
+            Directory.CreateDirectory(TexDir);
+            foreach (var (file, _, _, loop) in Anims)
+            {
+                string path = $"{Dir}/{file}.fbx";
+                var imp = AssetImporter.GetAtPath(path) as ModelImporter;
+                if (imp == null) { Debug.LogError($"[FinaleBoss] missing {path} — abort."); return; }
+
+                imp.animationType = ModelImporterAnimationType.Generic;
+                imp.importAnimation = true;
+                var clips = imp.defaultClipAnimations;
+                foreach (var c in clips) { c.loopTime = loop; c.name = file; }
+                imp.clipAnimations = clips;
+                imp.SaveAndReimport();
+
+                if (file == "boss_idle")   // one texture set serves all four (same model)
+                    imp.ExtractTextures(TexDir);
+            }
+            AssetDatabase.Refresh();
+
+            // ---- 2) animator: Idle loops by default; the rest fire on triggers, then return ----
+            AssetDatabase.DeleteAsset(CtrlPath);
+            var ctrl = AnimatorController.CreateAnimatorControllerAtPath(CtrlPath);
+            var sm = ctrl.layers[0].stateMachine;
+            var states = new Dictionary<string, AnimatorState>();
+
+            foreach (var (file, state, trigger, _) in Anims)
+            {
+                var clip = AssetDatabase.LoadAllAssetsAtPath($"{Dir}/{file}.fbx")
+                    .OfType<AnimationClip>().FirstOrDefault(c => !c.name.Contains("__preview__"));
+                if (clip == null) { Debug.LogWarning($"[FinaleBoss] no clip in {file}.fbx"); continue; }
+                var st = sm.AddState(state);
+                st.motion = clip;
+                states[state] = st;
+                if (trigger != null) ctrl.AddParameter(trigger, AnimatorControllerParameterType.Trigger);
+            }
+            if (!states.ContainsKey("Idle")) { Debug.LogError("[FinaleBoss] idle clip missing — abort."); return; }
+            sm.defaultState = states["Idle"];
+
+            foreach (var (_, state, trigger, _) in Anims)
+            {
+                if (trigger == null || !states.ContainsKey(state)) continue;
+                var into = sm.AddAnyStateTransition(states[state]);
+                into.AddCondition(AnimatorConditionMode.If, 0, trigger);
+                into.hasExitTime = false; into.duration = 0.15f; into.canTransitionToSelf = false;
+                var back = states[state].AddTransition(states["Idle"]);
+                back.hasExitTime = true; back.exitTime = 0.95f; back.duration = 0.25f;
+            }
+
+            // ---- 3) prefab: idle FBX as the body, URP materials, 10m grounded, +Z facing ----
+            var src = AssetDatabase.LoadAssetAtPath<GameObject>($"{Dir}/boss_idle.fbx");
+            var root = new GameObject("finale_boss_trueform");
+            var model = (GameObject)Object.Instantiate(src, root.transform);
+            model.name = "Model";
+
+            // Hunyuan exports face -Z (NPC-pipeline finding) — flip to +Z.
+            model.transform.localRotation = Quaternion.Euler(0f, 180f, 0f);
+
+            ConvertMaterialsToUrp(root);
+
+            // Normalize: renderer bounds → 10m tall, feet on y=0, centred on origin.
+            if (TryWorldBounds(root, out var b) && b.size.y > 0.001f)
+            {
+                float k = TargetHeight / b.size.y;
+                model.transform.localScale = Vector3.one * k;
+                if (TryWorldBounds(root, out b))
+                    model.transform.localPosition = new Vector3(-b.center.x, -b.min.y, -b.center.z);
+            }
+
+            var animator = root.GetComponentInChildren<Animator>() ?? model.AddComponent<Animator>();
+            animator.runtimeAnimatorController = ctrl;
+
+            Directory.CreateDirectory("Assets/Resources/CharacterModels");
+            var saved = PrefabUtility.SaveAsPrefabAsset(root, PrefabPath, out bool ok);

