+        /// <summary>Flat-shaded cone with correct outward normals. The original version added
+        /// BOTH windings on SHARED vertices to fake double-siding — RecalculateNormals then
+        /// averaged opposing faces to ~zero and the whole cone lit BLACK (user report: "black
+        /// tents" at the Silk Road camel camp). Per-face duplicated vertices, single outward
+        /// winding; the base faces down. Public so repair tooling can re-mesh baked scenes.</summary>
+        public static Mesh BuildConeMesh(float radius, float height, int segments = 14)
+        {
+            var verts = new List<Vector3>();
             var tris = new List<int>();
+            var apex = new Vector3(0, height, 0);
             for (int i = 0; i < segments; i++)
             {
