+                float a1 = (i + 1) * Mathf.PI * 2f / segments;
+                var b0 = new Vector3(Mathf.Cos(a0) * radius, 0f, Mathf.Sin(a0) * radius);
+                var b1 = new Vector3(Mathf.Cos(a1) * radius, 0f, Mathf.Sin(a1) * radius);
+
+                int v = verts.Count;                      // side (outward: apex → b1 → b0)
+                verts.Add(apex); verts.Add(b1); verts.Add(b0);
+                tris.AddRange(new[] { v, v + 1, v + 2 });
+
+                int w = verts.Count;                      // base wedge (facing down)
+                verts.Add(Vector3.zero); verts.Add(b0); verts.Add(b1);
+                tris.AddRange(new[] { w, w + 1, w + 2 });
