diff --git a/ChronoTraveler/Assets/Editor/TradeRepairTool.cs b/ChronoTraveler/Assets/Editor/TradeRepairTool.cs
new file mode 100644
index 0000000..fb40847
--- /dev/null
+++ b/ChronoTraveler/Assets/Editor/TradeRepairTool.cs
@@ -0,0 +1,89 @@
+using System.Collections.Generic;
+using UnityEditor;
+using UnityEditor.SceneManagement;
+using UnityEngine;
+
+namespace ChronoTraveler.EditorTools
+{
+    /// <summary>
+    /// In-place repair for the user-hand-tuned 60_TradeRoutes scene (the Build menu must NOT
+    /// be re-run — it would discard the tuning). Two fixes from the full-playthrough report:
+    ///   1. Tents rendered BLACK — the baked cone mesh had double-wound shared vertices, so
+    ///      RecalculateNormals averaged them to ~zero. Re-mesh every Tent_*/Canvas with the
+    ///      corrected flat-shaded cone (EraBuildEngine.BuildConeMesh).
+    ///   2. The Hunyuan prop models (camels/horse/cart/stupa/...) were placed with NO
+    ///      colliders — the player ghosted straight through them. Fit a BoxCollider to each
+    ///      prop's combined mesh bounds (computed in root-local space, so rotations don't
+    ///      inflate the box).
+    /// Idempotent: re-running skips props that already have a collider; re-meshing is harmless.
+    /// </summary>
+    public static class TradeRepairTool
+    {
+        private const string ScenePath = "Assets/Scenes/60_TradeRoutes.unity";
+
+        // The nine PlaceProp instances from TradeBazaarLayout (names = prefab names).
+        private static readonly string[] PropNames =
+        {
+            "prop_trade_camel_standing", "prop_trade_camel_standing_b", "prop_trade_camel_resting",
+            "prop_trade_horse", "prop_trade_milestone", "prop_trade_stupa",
+            "prop_trade_silk_bolts", "prop_trade_spice_sacks", "prop_trade_cart",
+        };
+
+        [MenuItem("ChronoTraveler/Content/Repair TradeRoutes (tents + prop colliders)")]
+        public static void Repair()
+        {
+            if (!EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo()) return;
+            var scene = EditorSceneManager.OpenScene(ScenePath, OpenSceneMode.Single);
+
+            // ---- 1) re-mesh the black tent canvases ----
+            int tents = 0;
+            foreach (var mf in Object.FindObjectsByType<MeshFilter>(FindObjectsSortMode.None))
+            {
+                if (mf.gameObject.name != "Canvas" || mf.transform.parent == null ||
+                    !mf.transform.parent.name.StartsWith("Tent_")) continue;
+                mf.sharedMesh = EraBuildEngine.BuildConeMesh(2.3f, 2.8f);
+                tents++;
+            }
+
+            // ---- 2) fit blocker colliders to the collider-less prop models ----
+            int fitted = 0;
+            foreach (var name in PropNames)
+            {
+                var go = GameObject.Find(name);
+                if (go == null) { Debug.LogWarning($"[TradeRepair] {name} not found — skipped."); continue; }
+                if (go.GetComponentInChildren<Collider>() != null) continue;   // already done
+
+                if (!TryLocalBounds(go, out var lb)) continue;
+                var bc = go.AddComponent<BoxCollider>();
+                bc.center = lb.center;
+                bc.size = lb.size;
+                fitted++;
+            }
+
+            EditorSceneManager.MarkSceneDirty(scene);
+            EditorSceneManager.SaveScene(scene);
+            Debug.Log($"[TradeRepair] done ✔  tents re-meshed: {tents}, prop colliders fitted: {fitted}. Scene saved.");
+        }
+
+        /// <summary>Combined mesh bounds in ROOT-local space (rotations don't inflate the box):
+        /// each child mesh's 8 bounds corners are mapped child→world→root-local.</summary>
+        private static bool TryLocalBounds(GameObject root, out Bounds bounds)

