@@ -0,0 +1,216 @@
+using System.Collections.Generic;
+using UnityEngine;
+using ChronoTraveler.Effects;   // Billboard
+
+namespace ChronoTraveler.World
+{
+    /// <summary>
+    /// Silk-road density + haze layer (user report: the bazaar read "big, empty, scattered").
+    /// Three cheap, purely-runtime treatments — no scene changes, unloads with the map:
+    ///   HAZE     — tighten the fog window and warm it to sand-gold, so the empty distance
+    ///              becomes "vastness behind dust" instead of a bare horizon;
+    ///   DUST     — a low drifting sand-mote particle layer following the player;
+    ///   CARAVAN  — a distant camel-train of dark billboard silhouettes walking the horizon
+    ///              line beyond the island edge (procedural sprite, ground-probed), plus a
+    ///              small falcon flock (SkyCreatures reuse) circling high.
+    /// Spawned by EnvironmentBootstrap on trade-map entry; idempotent per scene.
+    /// </summary>
+    [DisallowMultipleComponent]
+    public class TradeBazaarAmbience : MonoBehaviour
+    {
+        private const float CaravanRadius = 105f;    // beyond the ~130x110 island, over the sand sea
+        private const float CaravanSpeedDeg = 1.1f;  // a slow trade march, barely perceptible
+        private const int CamelCount = 5;
+
+        private Transform player;
+        private readonly List<Transform> camels = new List<Transform>();
+        private float caravanAngle = 205f;           // start off the entry sightline
+        private Vector3 anchor;                      // island centre-ish, captured at spawn
+
+        private void Start()
+        {
+            var p = GameObject.FindGameObjectWithTag("Player");
+            player = p != null ? p.transform : null;
+            anchor = player != null ? new Vector3(player.position.x, 0f, player.position.z) : Vector3.zero;
+
+            TightenHaze();
+            BuildDust();
+            BuildCaravan();
+            BuildFalcons();
+        }
+
+        // ---- C. haze: pull the fog in ~30% and warm it to dusk sand-gold ----
+        private void TightenHaze()
+        {
+            RenderSettings.fog = true;
+            RenderSettings.fogMode = FogMode.Linear;
+            RenderSettings.fogColor = new Color(0.80f, 0.69f, 0.53f);
+            RenderSettings.fogStartDistance = 42f;    // was ~60
+            RenderSettings.fogEndDistance = 260f;     // was ~380; backdrop ring at ~280 stays a ghost
+        }
+
+        // ---- A1. low drifting sand motes around the player ----
+        private void BuildDust()
+        {
+            var go = new GameObject("SandMotes");
+            go.transform.SetParent(transform, false);
+            var ps = go.AddComponent<ParticleSystem>();
+
+            var main = ps.main;
+            main.loop = true;
+            main.startLifetime = new ParticleSystem.MinMaxCurve(6f, 11f);
+            main.startSpeed = 0f;
+            main.startSize = new ParticleSystem.MinMaxCurve(0.05f, 0.16f);
+            main.startColor = new Color(0.86f, 0.76f, 0.58f, 0.35f);
+            main.maxParticles = 160;
+            main.simulationSpace = ParticleSystemSimulationSpace.World;
+
+            var emission = ps.emission;
+            emission.rateOverTime = 16f;
+
+            var shape = ps.shape;
+            shape.shapeType = ParticleSystemShapeType.Box;
+            shape.scale = new Vector3(46f, 5f, 46f);   // a low slab around the player
+            shape.position = new Vector3(0f, 2.2f, 0f);
+
+            var vel = ps.velocityOverLifetime;         // a steady sideways drift = wind
+            vel.enabled = true;
+            vel.x = new ParticleSystem.MinMaxCurve(0.5f, 1.1f);
+            vel.y = new ParticleSystem.MinMaxCurve(-0.06f, 0.10f);
+            vel.z = new ParticleSystem.MinMaxCurve(-0.25f, 0.25f);
+
+            var col = ps.colorOverLifetime;            // fade in, hold, fade out
+            col.enabled = true;
+            var grad = new Gradient();
+            grad.SetKeys(
+                new[] { new GradientColorKey(Color.white, 0f), new GradientColorKey(Color.white, 1f) },
+                new[] { new GradientAlphaKey(0f, 0f), new GradientAlphaKey(1f, 0.2f),
+                        new GradientAlphaKey(1f, 0.75f), new GradientAlphaKey(0f, 1f) });
+            col.color = grad;
+
+            var renderer = ps.GetComponent<ParticleSystemRenderer>();
+            renderer.material = DustMaterial();
+            renderer.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
+        }
+
+        // Same soft-dot recipe as AmbientVFX's star motes (proven in China) — URP particle

