+                if (t.GetComponentInChildren<Collider>() != null) continue;
+                if (!TryLocalBounds(t.gameObject, out var lb)) continue;
+                var bc = t.gameObject.AddComponent<BoxCollider>();
+                bc.center = lb.center; bc.size = lb.size;
+                bowls++;
+            }
+
