diff --git a/ChronoTraveler/Assets/Scripts/World/GroundSnap.cs b/ChronoTraveler/Assets/Scripts/World/GroundSnap.cs
new file mode 100644
index 0000000..34700d0
--- /dev/null
+++ b/ChronoTraveler/Assets/Scripts/World/GroundSnap.cs
@@ -0,0 +1,43 @@
+using System.Collections;
+using UnityEngine;
+
+namespace ChronoTraveler.World
+{
+    /// <summary>
+    /// Drops a model so its ANIMATED silhouette stands on the ground. The finale trueform
+    /// was baked feet-at-origin from the FBX bind pose, but the Animator's idle pose shifts
+    /// the skeleton — the boss hovered above the platform (user play report). Bind-time
+    /// normalization can't know the animated pose, so this measures it live: wait two
+    /// frames for the Animator to settle, take the combined renderer bounds, raycast for
+    /// the ground (ignoring the model's own hierarchy) and shift so bounds.min.y sits on
+    /// the hit point. Re-runs are harmless; works for any future rigged swap-in.
+    /// </summary>
+    public class GroundSnap : MonoBehaviour
+    {
+        private IEnumerator Start()
+        {
+            yield return null;
+            yield return null;   // Animator has applied the idle pose by now
+
+            var renderers = GetComponentsInChildren<Renderer>();
+            if (renderers.Length == 0) yield break;
+            var b = renderers[0].bounds;
+            foreach (var r in renderers) b.Encapsulate(r.bounds);
+
+            // Ground under the model, skipping our own colliders (the trigger root carries
+            // the interact/blocker sphere, which a plain raycast would hit first).
+            float groundY = float.NaN;
+            var origin = new Vector3(b.center.x, b.center.y + 20f, b.center.z);
+            foreach (var hit in Physics.RaycastAll(origin, Vector3.down, 200f))
+            {
+                if (hit.transform.IsChildOf(transform.root)) continue;
+                if (float.IsNaN(groundY) || hit.point.y > groundY) groundY = hit.point.y;
+            }
+            if (float.IsNaN(groundY)) yield break;   // nothing below (mid-fall?) — leave as-is
+
+            float offset = groundY - b.min.y;
+            if (Mathf.Abs(offset) < 0.01f) yield break;
+            transform.position += Vector3.up * offset;
+        }
+    }
+}

