+namespace ChronoTraveler.EditorTools
+{
+    /// <summary>
+    /// Bakes the decimated Xuanji OBJ (output of tools/decimate_xuanji.py) into
+    /// <c>Resources/CharacterModels/xuanji.prefab</c> — the drop-in 3D body that
+    /// CompanionController prefers over its 2D sprite fallback. Floating-mascot
+    /// specifics vs NPCModelSetupTool: the pivot is the renderer-bounds CENTRE
+    /// (the body hangs on a hover anchor — no feet, no ground) and normalisation
+    /// is by body LENGTH (longest horizontal axis; the pose is a curled lying fox),
+    /// not by height.
+    /// </summary>
+    public static class XuanjiModelTool
+    {
+        private const string SrcModel  = "Assets/Art/Characters/Companion/xuanji_body.obj";
+        private const string SrcAlbedo = "Assets/Art/Characters/Companion/xuanji_basecolor.png";
+        private const string SrcNormal = "Assets/Art/Characters/Companion/xuanji_normal.png";
+        private const string OutDir    = "Assets/Resources/CharacterModels";
+        private const string MatDir    = OutDir + "/xuanji_Mats";
+
+        private const float BodyLength = 0.6f;   // metres along the longest horizontal axis (Paimon-scale)
+        private const float FaceYaw    = 180f;   // Hunyuan front-view exports face -Z; tweak + re-run if Play shows her backwards
+
+        [MenuItem("ChronoTraveler/Content/Build Xuanji 3D Body")]
+        public static void Build()
+        {
+            var model = AssetDatabase.LoadAssetAtPath<GameObject>(SrcModel);
+            if (model == null)
+            {
+                Debug.LogError($"[Xuanji3D] model not found at {SrcModel} — run tools/decimate_xuanji.py first.");
+                return;
+            }
+
+            Directory.CreateDirectory(OutDir);
+            Directory.CreateDirectory(MatDir);
+            AssetDatabase.Refresh();
+
+            var inst = (GameObject)PrefabUtility.InstantiatePrefab(model);
+            if (inst == null) inst = Object.Instantiate(model);
+            PrefabUtility.UnpackPrefabInstance(inst, PrefabUnpackMode.Completely, InteractionMode.AutomatedAction);
+            inst.name = "Model";
+            inst.transform.position = Vector3.zero;
+            inst.transform.rotation = Quaternion.Euler(0f, FaceYaw, 0f);
+
+            ApplyMaterial(inst);
+
+            var root = new GameObject("xuanji");
+            inst.transform.SetParent(root.transform, true);
+
+            if (TryWorldBounds(inst, out var pre))
+            {
+                float len = Mathf.Max(pre.size.x, pre.size.z);
+                if (len > 0.0001f) inst.transform.localScale *= BodyLength / len;
+            }
+            if (TryWorldBounds(inst, out var b))
+                inst.transform.position -= b.center;   // pivot = bounds centre (hover anchor)
+
+            string prefabPath = $"{OutDir}/xuanji.prefab";
+            var saved = PrefabUtility.SaveAsPrefabAsset(root, prefabPath, out bool ok);
+            Object.DestroyImmediate(root);
+
+            if (ok && saved != null)
+            {
+                AssetDatabase.SaveAssets();
+                EditorGUIUtility.PingObject(saved);
+                Selection.activeObject = saved;
+                Debug.Log($"[Xuanji3D] built {prefabPath} (length≈{BodyLength}m, yaw={FaceYaw})");
+            }
+            else
+            {
+                Debug.LogError($"[Xuanji3D] failed to save prefab at {prefabPath}");
+            }
+        }
+
+        private static void ApplyMaterial(GameObject root)
+        {
+            var shader = Shader.Find("Universal Render Pipeline/Lit");
+            if (shader == null)
+            {
+                Debug.LogWarning("[Xuanji3D] URP/Lit shader not found — leaving import materials as-is.");
+                return;
+            }
+
+            EnsureNormalMapImport(SrcNormal);
+            var albedo = AssetDatabase.LoadAssetAtPath<Texture2D>(SrcAlbedo);
+            var normal = AssetDatabase.LoadAssetAtPath<Texture2D>(SrcNormal);
+
+            var m = new Material(shader) { name = "xuanji_body" };
+            if (albedo != null) m.SetTexture("_BaseMap", albedo);
+            if (normal != null) { m.SetTexture("_BumpMap", normal); m.EnableKeyword("_NORMALMAP"); }
+            m.SetFloat("_Metallic", 0f);
+            m.SetFloat("_Smoothness", 0.35f);
+
+            string path = AssetDatabase.GenerateUniqueAssetPath($"{MatDir}/{m.name}.mat");
+            AssetDatabase.CreateAsset(m, path);
+
+            foreach (var r in root.GetComponentsInChildren<Renderer>(true))
+            {
+                var mats = new Material[r.sharedMaterials.Length];
+                for (int i = 0; i < mats.Length; i++) mats[i] = m;
+                r.sharedMaterials = mats;
+            }
+        }
+
+        private static void EnsureNormalMapImport(string path)
+        {
+            var ti = AssetImporter.GetAtPath(path) as TextureImporter;
+            if (ti != null && ti.textureType != TextureImporterType.NormalMap)
+            {
+                ti.textureType = TextureImporterType.NormalMap;
+                ti.SaveAndReimport();

