+using System.Collections.Generic;
+using System.Linq;
+using UnityEditor;
+using UnityEditor.SceneManagement;
+using UnityEngine;
+using UnityEngine.SceneManagement;
+using ChronoTraveler.World;
+
+namespace ChronoTraveler.EditorTools
+{
+    /// <summary>
+    /// Batch E: plants the era lore steles (8 interactable culture cards per era) into the four
+    /// hand-tuned era scenes WITHOUT rebuilding anything. Anchor-based placement — each stele
+    /// stands a few meters from a landmark the player already visits (NPCs, fragments, spawn,
+    /// battle triggers), ground-snapped, facing its anchor. Idempotent: a marker whose object
+    /// name already exists in the scene is skipped, so hand-moved steles survive re-runs.
+    /// Trade (60_TradeRoutes) already has its 10 steles from the bazaar build — not touched.
+    /// Run with an era scene open: ChronoTraveler ▸ Content ▸ Place Lore Steles (open scene).
+    /// </summary>
+    public static class LoreStelePlacementTool
+    {
+        // Canon slug table — must match the <era>.lore.<slug>.title/.body keys in ui_strings.
+        private static readonly Dictionary<string, string[]> Slugs = new Dictionary<string, string[]>
+        {
+            ["china"]  = new[] { "sinan", "bamboo", "silk", "ding", "dujiangyan", "lacquer", "calendar", "measures" },
+            ["egypt"]  = new[] { "maat", "nilometer", "obelisk", "scarab", "suncalendar", "shaduf", "faience", "embalming" },
+            ["greece"] = new[] { "ostracism", "antikythera", "mask", "academy", "trireme", "wreath", "hippocratic", "parthenon" },
+            ["rome"]   = new[] { "twelvetables", "aquila", "triumph", "baths", "pantheon", "milliarium", "juliancal", "spqr" },
+        };
+
+        [MenuItem("ChronoTraveler/Content/Place Lore Steles (open scene)")]
+        public static void PlaceSteles()
+        {
+            string scene = SceneManager.GetActiveScene().name;
+            string era = EraFromScene(scene);
+            if (era == null)
+            {
+                Debug.LogWarning($"[LoreSteles] open scene '{scene}' is not one of the four target era maps " +
+                                 "(20_China / 30_Egypt / 40_Greece / 50_Rome) — nothing placed.");
+                return;
+            }
+
+            var anchors = CollectAnchors();
+            if (anchors.Count == 0)
+            {
+                Debug.LogWarning("[LoreSteles] no anchors (NPCs / fragments / spawns / triggers) found in scene.");
+                return;
+            }
+
+            int placed = 0, kept = 0;
+            string[] slugs = Slugs[era];
+            for (int i = 0; i < slugs.Length; i++)
+            {
+                string keyPrefix = $"{era}.lore.{slugs[i]}";
+                string objName = $"LoreMarker_{era}_{slugs[i]}";
+                if (GameObject.Find(objName) != null) { kept++; continue; }   // hand-tuned survivor
+
+                Vector3 anchor = anchors[i % anchors.Count];
+                Vector3 pos = FindSpotNear(anchor, seed: i);
+                float yaw = Quaternion.LookRotation(
+                    new Vector3(anchor.x - pos.x, 0f, anchor.z - pos.z).sqrMagnitude > 0.01f
+                        ? new Vector3(anchor.x - pos.x, 0f, anchor.z - pos.z)
+                        : Vector3.forward).eulerAngles.y;
+
