+using System.Collections.Generic;
+using System.Linq;
+using UnityEditor;
+using UnityEditor.SceneManagement;
+using UnityEngine;
+using UnityEngine.SceneManagement;
+using ChronoTraveler.World;
+
+namespace ChronoTraveler.EditorTools
+{
+    /// <summary>
+    /// 时代勘误 (audit §8.2 minimal prototype): plants three exhibit sites into 20_China, each
+    /// a row of three look-alike display pedestals where exactly one item is an anachronism.
+    /// Judgment lives in the item cards' text, not in visual tells (audit's own warning), so
+    /// every pedestal uses the same stone + muted item silhouette. Idempotent by object name —
+    /// hand-moved pedestals survive re-runs. Run with 20_China open:
+    /// ChronoTraveler ▸ Content ▸ Place Era Errata (China, open scene).
+    /// </summary>
+    public static class ErrataSetupTool
+    {
+        private struct Item { public string slot; public bool errata; }
+        private struct Site { public string id; public Item[] items; }
+
+        // ui_strings key = errata.china.<site>.<slot>.title/.body/.note
+        private static readonly Site[] Sites =
+        {
+            new Site { id = "china_s1", items = new[] {           // 书案 the scholar's desk
+                new Item { slot = "a", errata = false },          // 竹简
+                new Item { slot = "b", errata = true  },          // 线装书 (宋以后)
+                new Item { slot = "c", errata = false } } },      // 毛笔
+            new Site { id = "china_s2", items = new[] {           // 乐台 the music terrace
+                new Item { slot = "a", errata = false },          // 编钟
+                new Item { slot = "b", errata = false },          // 古琴
+                new Item { slot = "c", errata = true  } } },      // 唢呐 (金元传入)
+            new Site { id = "china_s3", items = new[] {           // 兵器架 the weapon rack
+                new Item { slot = "a", errata = false },          // 青铜戈
+                new Item { slot = "b", errata = false },          // 环首刀
+                new Item { slot = "c", errata = true  } } },      // 双马镫 (东晋)
+        };
+
+        [MenuItem("ChronoTraveler/Content/Place Era Errata (China, open scene)")]
+        public static void PlaceErrata()
+        {
+            if (!SceneManager.GetActiveScene().name.ToLowerInvariant().Contains("china"))
+            {
+                Debug.LogWarning("[Errata] open 20_China first — the errata prototype is China-only.");
+                return;
+            }
+
+            // Site anchors: spawn area first (the audit suggests the entrance zone), then NPCs.
+            var anchors = new List<Vector3>();
+            anchors.AddRange(Object.FindObjectsByType<ChronoTraveler.Core.SpawnPoint>(
+                FindObjectsInactive.Include, FindObjectsSortMode.InstanceID).Select(o => o.transform.position));
+            anchors.AddRange(Object.FindObjectsByType<ChronoTraveler.NPC.NPCController>(
+                FindObjectsInactive.Include, FindObjectsSortMode.InstanceID).Select(o => o.transform.position));
+            if (anchors.Count == 0)
+            { Debug.LogWarning("[Errata] no spawn/NPC anchors found in scene."); return; }
+
+            int placed = 0, kept = 0;
+            for (int s = 0; s < Sites.Length; s++)
+            {
+                Vector3 anchor = anchors[s % anchors.Count];
+                // one row of three pedestals, ~5m out from the anchor, 1.5m apart
+                float baseBearing = (35f + s * 121f) * Mathf.Deg2Rad;
+                Vector3 outward = new Vector3(Mathf.Sin(baseBearing), 0f, Mathf.Cos(baseBearing));
+                Vector3 side = Vector3.Cross(Vector3.up, outward);
+                Vector3 rowCenter = anchor + outward * 5f;
+
+                for (int i = 0; i < Sites[s].items.Length; i++)
+                {
+                    var item = Sites[s].items[i];
+                    string objName = $"Errata_{Sites[s].id}_{item.slot}";
+                    if (GameObject.Find(objName) != null) { kept++; continue; }
+
+                    Vector3 flat = rowCenter + side * ((i - 1) * 1.5f);
+                    float gy = LoreStelePlacementTool.SafeGroundY(flat.x, flat.z, float.NaN);
+                    if (float.IsNaN(gy) || Mathf.Abs(gy - anchor.y) > 2.5f) gy = anchor.y;
+                    BuildPedestal(objName, $"errata.china.{Sites[s].id}.{item.slot}", Sites[s].id,
+                                  item.errata, new Vector3(flat.x, gy, flat.z), anchor, i);
+                    placed++;
+                }
+            }
+
+            EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());
+            EditorSceneManager.SaveOpenScenes();
+            Debug.Log($"[Errata] placed {placed} exhibit pedestals, kept {kept} existing (scene saved). " +
+                      "Sites: s1 书案 / s2 乐台 / s3 兵器架 — hand-move rows freely; re-runs keep your moves.");
+        }
+
+        /// <summary>Same stone pedestal for every exhibit (no visual tells); the item on top is
+        /// an abstract muted silhouette that only differentiates the stations.</summary>
+        private static void BuildPedestal(string objName, string keyPrefix, string siteId,
+                                          bool errata, Vector3 pos, Vector3 anchor, int index)
+        {
+            var root = new GameObject(objName);
+            root.transform.position = pos;
+            Vector3 look = new Vector3(anchor.x - pos.x, 0f, anchor.z - pos.z);
+            if (look.sqrMagnitude > 0.01f) root.transform.rotation = Quaternion.LookRotation(look);
+
+            var stone = EraBuildEngine.Matte(new Color(0.52f, 0.49f, 0.44f));
+            var cloth = EraBuildEngine.Matte(new Color(0.42f, 0.30f, 0.24f));
+
+            void Block(string n, PrimitiveType type, Vector3 lp, Vector3 ls, Material m)
+            {
+                var b = GameObject.CreatePrimitive(type);
+                b.name = n; b.transform.SetParent(root.transform, false);
+                b.transform.localPosition = lp; b.transform.localScale = ls;
+                b.GetComponent<MeshRenderer>().sharedMaterial = m;
+                Object.DestroyImmediate(b.GetComponent<Collider>());
+            }
+            Block("Base", PrimitiveType.Cube, new Vector3(0, 0.08f, 0), new Vector3(0.7f, 0.16f, 0.7f), stone);
+            Block("Column", PrimitiveType.Cube, new Vector3(0, 0.5f, 0), new Vector3(0.46f, 0.7f, 0.46f), stone);
+            Block("Top", PrimitiveType.Cube, new Vector3(0, 0.9f, 0), new Vector3(0.6f, 0.08f, 0.6f), cloth);
+            // muted item silhouette — shape varies by station only, never by correctness

