+using UnityEngine;
+using ChronoTraveler.Core;
+
+namespace ChronoTraveler.Cutscene
+{
+    /// <summary>
+    /// 序章《星引之约》引导链（spec 2026-07-16）。仅当「枢纽 && 星晶数==0 &&
+    /// prologue_depart 未播」时激活：拍1(enter_hub) 由 MapEntryCutsceneTrigger 照常首入播，
+    /// 其后本组件按顺序在 星图点→五门廊→华夏门旁 竖起星光标记，玩家走近即 PlayOnce
+    /// 对应段。有进度的老档(≥1 星晶)与已完成序章的档零触发；序列缺失(文案未入库)则
+    /// 蛰伏——与 CG/视频同一免疫哲学。自启动+DDOL，镜像 FinaleTrigger。
+    /// </summary>
+    public class PrologueGuide : MonoBehaviour
+    {
+        private const string BeatStarmap = "prologue_starmap";
+        private const string BeatGates   = "prologue_gates";
+        private const string BeatDepart  = "prologue_depart";
+        private const float  TriggerRadius = 2.6f;
+
+        public static PrologueGuide Instance { get; private set; }
+        private bool subFlow;
+        private bool activeInHub;
+        private string pendingBeat;
+        private Vector3 pendingPos;
+        private GameObject marker;
+        private Transform player;
+
+        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
+        private static void Bootstrap()
+        {
+            if (Instance == null) new GameObject("[PrologueGuide]").AddComponent<PrologueGuide>();
+        }
+
+        private void Awake()
+        {
+            if (Instance != null && Instance != this) { Destroy(gameObject); return; }
+            Instance = this;
+            DontDestroyOnLoad(gameObject);
+        }
+
+        private void Update()
+        {
+            if (!subFlow && SceneFlowManager.Instance != null)
+            {
+                SceneFlowManager.Instance.OnMapEntered += HandleMapEntered;
+                subFlow = true;
+            }
+            if (!activeInHub) return;
+            var cm = CutsceneManager.Instance;
+            if (cm == null || cm.IsPlaying) return;
+            if (GameManager.Instance == null || GameManager.Instance.CurrentState != GameState.Exploring) return;
+
+            if (pendingBeat == null) { Advance(); return; }
+
+            if (player == null)
+                player = FindFirstObjectByType<ChronoTraveler.Player.SimplePlayerController>()?.transform;
+            if (player == null) return;
+            if ((player.position - pendingPos).sqrMagnitude <= TriggerRadius * TriggerRadius)
+            {
+                string beat = pendingBeat;
+                pendingBeat = null;
+                ClearMarker();
+                cm.PlayOnce(beat);
+            }
+        }
+
+        private void OnDestroy()
+        {
+            if (subFlow && SceneFlowManager.Instance != null)
+                SceneFlowManager.Instance.OnMapEntered -= HandleMapEntered;
+        }
+
+        private void HandleMapEntered(string mapScene)
+        {
+            activeInHub = false; pendingBeat = null; player = null; ClearMarker();
+            if (string.IsNullOrEmpty(mapScene) || !mapScene.ToLowerInvariant().Contains("hub")) return;
+            if (EraProgress.Instance == null || EraProgress.Instance.TokenCount > 0) return;
+            var cm = CutsceneManager.Instance;
+            if (cm == null || cm.HasPlayed(BeatDepart)) return;
+            activeInHub = true;
+        }
+
+        /// <summary>拍1 播毕后按 HasPlayed 顺序推进；序列缺失或定位失败则整链蛰伏。</summary>
+        private void Advance()
+        {
+            var cm = CutsceneManager.Instance;
+            if (!cm.HasPlayed("enter_hub")) return;   // 拍1 归 MapEntryCutsceneTrigger 管
+            string next = !cm.HasPlayed(BeatStarmap) ? BeatStarmap
+                        : !cm.HasPlayed(BeatGates)   ? BeatGates
+                        : !cm.HasPlayed(BeatDepart)  ? BeatDepart : null;
+            if (next == null || !cm.HasSequence(next)) { activeInHub = false; return; }
+            Vector3? pos = ResolveBeatPos(next);
+            if (pos == null) { activeInHub = false; return; }
+            pendingBeat = next; pendingPos = pos.Value;
+            SpawnMarker(pos.Value);
+        }
+
+        /// <summary>锚定场景已知物定位三站：星图点=出生点→门群质心的半途；五门廊=门群质心；
+        /// 出发点=华夏门前 3m（朝出生点方向让开门口）。任一锚缺失 → 返回 null 整链蛰伏。</summary>
+        private Vector3? ResolveBeatPos(string beat)
+        {
+            var portals = FindObjectsByType<ChronoTraveler.World.Portal>(
+                FindObjectsInactive.Include, FindObjectsSortMode.InstanceID);
+            if (portals.Length == 0) return null;
+            Vector3 centroid = Vector3.zero;
+            Vector3? china = null;
+            foreach (var p in portals)
+            {
+                centroid += p.transform.position;
+                if ((p.TargetMapScene ?? "").ToLowerInvariant().Contains("china"))
+                    china = p.transform.position;
+            }
+            centroid /= portals.Length;
+            var spawnPt = FindFirstObjectByType<SpawnPoint>();

